use std::rc::{Rc, Weak};
use std::cell::RefCell;

pub struct Node {
    pub value: i32,
    // Raw pointers for edges — no lifetime issues, no RefCell runtime checks.
    next: *mut Node,
    prev: *mut Node,
    // Weak reference prevents Rc cycles from leaking memory.
    parent: Option<Weak<RefCell<Node>>>,
}

impl Node {
    pub fn new(value: i32) -> Self {
        Self {
            value,
            next: std::ptr::null_mut(),
            prev: std::ptr::null_mut(),
            parent: None,
        }
    }
}

/// A safe wrapper. All mutation uses the pointer logic in the `unsafe` blocks,
// but the public interface is safe Rust.
pub struct SafeList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl SafeList {
    pub fn new() -> Self {
        Self { head: None, tail: None }
    }

    /// Append a node. We use raw pointer writes so we never trigger
    /// overlapping `RefCell` borrows.
    pub fn push_back(&mut self, value: i32) {
