/// A small doubly-linked graph container.
#[derive(Debug, Default)]
struct Graph {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl Graph {
    fn push_back(&mut self, node: Rc<RefCell<Node>>) {
        match self.tail.take() {
            None => {
                // First node
                self.head = Some(Rc::clone(&node));
                self.tail = Some(node);
            }
            Some(old_tail_rc) => {
                // Link old tail -> new node
                old_tail_rc.borrow_mut().next = Some(Rc::clone(&node));
                // Link new node -> old tail
                node.borrow_mut().prev = Some(old_tail_rc);
                // Update tail pointer
                self.tail = Some(node);
            }
        }
    }

    /// Mutate a node in-place by value reference, even while it lives in the graph.
    fn mutate_head(&self, new_val: i32) {
        if let Some(h) = &self.head {
            h.borrow_mut().value = new_val;
        }
    }

    /// Print values by walking the list — demonstrates safe shared borrows.
    fn print(&self) {
        let mut current = self.head.as_ref().map(Rc::clone);
        print!("Graph: ");
        while let Some(node_rc) = current {
            let val = node_rc.borrow().value;
            print!("{} ", val);
            current = node_rc.borrow().next.as_ref().map(Rc::clone);
        }
        println!();
    }
}

fn main() {
    let mut graph = Graph::default();

    let a = Node::new(10);
    let b = Node::new(20);
    let c = Node::new(30);

    graph.push_back(a);
    graph.push_back(b);
    graph.push_back(c);

    graph.print(); // 10 20 30

    // Safe mutation: we borrow a node, change it, and drop the borrow immediately.
    graph.mutate_head(99);
