use std::collections::{HashMap, HashSet};

/// A small directed graph built without explicit lifetime annotations.
/// Nodes are owned by the Arena; edges are stored as integer IDs.
/// Back-edges / arbitrary references are stored in a HashMap inside RefCell.
pub struct Arena {
    nodes: Vec<RefCell<Node>>,
}

#[derive(Debug, Default)]
pub struct Node {
    pub id: usize,
    pub payload: String,
    /// Out-edges: target id -> (optional edge label/data)
    pub out_edges: Vec<(usize, String)>,
    /// Back-edges / arbitrary references stored safely for mutation
    pub back_refs: RefCell<HashMap<usize, String>>,
}

impl Arena {
    pub fn new() -> Self {
        Arena { nodes: Vec::new() }
    }

    /// Allocate a node and return its handle (id).
    pub fn add_node(&mut self, payload: String) -> usize {
        let id = self.nodes.len();
        self.nodes.push(RefCell::new(Node {
            id,
            payload,
            out_edges: Vec::new(),
            back_refs: RefCell::new(HashMap::new()),
        }));
        id
    }

    /// Add a directed edge from -> to.
    pub fn link(&mut self, from: usize, to: usize, label: String) {
        // Verify targets exist.
        assert!(from < self.nodes.len(), "Invalid source node id: {}", from);
        assert!(to < self.nodes.len(), "Invalid target node id: {}", to);

        self.nodes[from].borrow_mut().out_edges.push((to, label.clone()));

        // Also register the back-reference safely inside RefCell.
        // No borrow checker conflicts here because we borrow `from` and `to` separately.
        self.nodes[to].borrow_mut().back_refs.borrow_mut().insert(from, label);
    }

