                    node.out_edges.iter().take(1).map(|(t, _)| *t).collect()
                }
            };

            for target in edges {
                if target < self.nodes.len() {
                    stack.push(target);
                }
            }
        }
        result
    }

    /// Print the graph layout, including back-refs to prove references are intact.
    pub fn print_graph(&self) {
