use std::cell::RefCell;
use std::rc::Rc;

pub struct List<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
}

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

impl<T> List<T> {
    pub fn new() -> Self {
        List { head: None, tail: None }
    }

    pub fn push_front(&mut self, value: T) {
        let node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        if let Some(old_head) = self.head.clone() {
            old_head.borrow_mut().prev = Some(node.clone());
        } else {
            self.tail = Some(node.clone());
        }

        self.head = Some(node);
    }

    pub fn push_back(&mut self, value: T) {
        let node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.clone() {
            old_tail.borrow_mut().next = Some(node.clone());
        } else {
            self.head = Some(node.clone());
        }

        self.tail = Some(node);
    }

    /// Removes and returns the last element.
    /// This method is safe but requires cloning pointer handles
    /// and explicitly dropping borrows to avoid borrow conflicts.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.clone()?;

        // We clone the Rc *before* borrowing so we can navigate
        // without holding a borrow across other borrows.
        let prev_rc = {
            // Borrow only long enough to clone the inner pointer
            let b = tail_rc.borrow();
            b.prev.clone()
        };

        // Extract the value
        let value = Rc::try_unwrap(tail_rc).ok()?.into_inner().value;

        self.tail = prev_rc.clone();
        if let Some(p) = prev_rc {
            // Explicit drop of the borrow guard is not needed
            // if we borrow and immediately let the guard fall out
            // of scope, but we make sure not to borrow `tail_rc`
            // (now dropped) accidentally.
            p.borrow_mut().next = None;
        } else {
            self.head = None;
        }

        Some(value)
    }

    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }
}

