    b.prev.set(Some(Rc::clone(a)));
}

fn unlink(node: &Rc<Node>) {
    let prev = node.prev.take();
    let next = node.next.take();

    if let Some(p) = prev {
        p.next.set(next.as_ref().map(Rc::clone));
    }
    if let Some(n) = next {
        n.prev.set(prev.as_ref().map(Rc::clone));
    }
}

fn insert_after(after: &Rc<Node>, node: &Rc<Node>) {
    let old_next = after.next.take();
    after.next.set(Some(Rc::clone(node)));

    if let Some(old) = old_next {
        old.prev.set(Some(Rc::clone(node)));
    }
    node.prev.set(Some(Rc::clone(after)));
    node.next.set(old_next);
}

fn main() {
    // Build: 1 <-> 2 <-> 3
    let n1 = Node::new(1);
    let n2 = Node::new(2);
    let n3 = Node::new(3);

    link(&n1, &n2);
    link(&n2, &n3);

    // Mutate links safely while holding multiple Rc handles
    unlink(&n2); // removes 2; list is now 1 <-> 3

    let n4 = Node::new(4);
    insert_after(&n1, &n4); // 1 <-> 4 <-> 3

    // Read back through Rc (no borrow checker fight)
    println!("Value: {}", n1.value);
    println!("Next: {:?}", n1.next.get().as_ref().map(|n| n.value));
    println!("Next's next: {:?}", n1.next.get().as_ref()
        .and_then(|n| n.next.get().as_ref().map(|nn| nn.value)));

    // Verify n3's prev points back through n4
    assert_eq!(n3.prev.get().as_ref().map(|r| r.value), Some(4));
}
```

### Why this avoids your lifetime errors

| Approach | Problem | Fix above |
|---|---|---|
| `Rc<Node>` with `&mut` borrows | You can't borrow one node mutably while another `Rc` holds it | `Cell<Option<Rc<Node>>>` gives mutable access to the *pointer* without borrowing the `Node` |
| `Rc<RefCell<Node>>` | Borrow-checks the *inside* of the node; holding `Ref` on A and B simultaneously causes runtime panic or impossible borrow graphs | We never borrow the `Node` contents mutably; we only move `Rc<Node>` handles via `Cell` |
| Raw lifetimes (`&'a`) | Circular references require self-referential structs (impossible safely in safe Rust) | `Rc` creates shared ownership; `Cell` allows mutation of the link field without a borrow of the target node |

