```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A doubly-linked list node.
struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>, // Weak breaks the cycle
}

/// The list handle.
pub struct LinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl LinkedList {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
        }
    }

    /// Push to the front.
    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }));

        if let Some(old_head) = self.head.take() {
            // Link old head back to new node via weak pointer
            old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
            // Link new node forward to old head
            new_node.borrow_mut().next = Some(old_head);
        }

        self.head = Some(Rc::clone(&new_node));
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }));

        if let Some(old_tail) = self.tail.take() {
            old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
            new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
        }

        self.tail = Some(Rc::clone(&new_node));
        if self.head.is_none() {
            self.head = Some(new_node);
        }
    }

    /// Pop from the front. Returns the value or None if empty.
    pub fn pop_front(&mut self) -> Option<i32> {
        let old_head = self.head.take()?;
        let value = old_head.borrow().value;

        // Take over the next link, breaking old_head's link to the rest of the list
        if let Some(new_head) = old_head.borrow_mut().next.take() {
            new_head.borrow_mut().prev = None;
            self.head = Some(new_head);
        } else {
            // List is now empty
            self.tail = None;
        }

        Some(value)
    }

    /// Print the list from head to tail.
    pub fn display(&self) {
        let mut current = self.head.clone();
        while let Some(node) = current {
            let val = node.borrow().value; // temporary borrow
            print!("{} ", val);
            current = node.borrow().next.clone(); // read and clone Rc
        }
        println!();
    }
}

fn main() {
    let mut list = LinkedList::new();

    list.push_back(10);
    list.push_front(5);
    list.push_back(20);
    list.push_front(1);

    println!("List contents:");
    list.display(); // 1 5 10 20

    println!("Popped front: {:?}", list.pop_front()); // Some(1)
    println!("After pop:");
    list.display(); // 5 10 20
}
```

