/// A graph node that can be mutated even while other nodes point to it.
pub struct Node {
    pub name: String,
    /// Outgoing edges: owned references so we can traverse forward.
    pub out: Vec<Rc<RefCell<Node>>>,
    /// Incoming edges: weak references so we don't create cycles.
    pub incoming: Vec<Weak<RefCell<Node>>>,
}

impl Node {
    /// Creates a new node wrapped in an Rc so it can be shared.
    pub fn new(name: &str) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            name: name.to_string(),
            out: Vec::new(),
            incoming: Vec::new(),
        }))
    }

    /// Links `from` -> `to` and records the back-link as Weak.
    pub fn connect(from: &Rc<RefCell<Node>>, to: &Rc<RefCell<Node>>) {
