        // We clone the Rc pointer (not the inner data), so this is safe.
        from.borrow_mut().out.push(Rc::clone(to));

        // Statement 2: mutably borrow `to` and record the weak back-link.
        // The previous borrow_mut was dropped at the end of statement 1.
        to.borrow_mut().incoming.push(Rc::downgrade(from));
    }

    /// Prints the state of this node and all its neighbors.
    pub fn print_state(node: &Rc<RefCell<Node>>) {
        let n = node.borrow(); // immutable borrow

        println!("Node: {}", n.name);
        println!("  Outgoing edges: {}", n.out.len());
        for neighbor in &n.out {
