```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

pub struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

impl Node {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

pub struct List {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Weak<RefCell<Node>>>,
}

impl List {
    pub fn new() -> Self {
        List { head: None, tail: None }
    }

    /// Add to the end. Uses weak refs for `prev` so we don't create cycles.
    pub fn push_back(&mut self, value: i32) {
        let node = Node::new(value);

        match self.tail.take() {
            Some(weak_tail) => {
                if let Some(tail_rc) = weak_tail.upgrade() {
                    // Link old tail -> new node
                    tail_rc.borrow_mut().next = Some(node.clone());
                    // Link new node <- old tail (weak so tail can be freed)
                    node.borrow_mut().prev = Some(Rc::downgrade(&tail_rc));
                    self.tail = Some(Rc::downgrade(&node));
                } else {
                    // Previous tail was dropped; rebuild from this node
                    self.head = Some(node.clone());
                    self.tail = Some(Rc::downgrade(&node));
                }
            }
            None => {
                // Empty list
                self.head = Some(node.clone());
                self.tail = Some(Rc::downgrade(&node));
            }
        }
    }

    /// Remove from the end and return its value.
    pub fn pop_back(&mut self) -> Option<i32> {
        let weak_tail = self.tail.take()?;
        let tail_rc = weak_tail.upgrade()?;

        let value = tail_rc.borrow().value;
        let prev_weak = tail_rc.borrow().prev.clone();

        if let Some(weak_prev) = prev_weak {
            if let Some(prev_rc) = weak_prev.upgrade() {
                prev_rc.borrow_mut().next = None;
                self.tail = Some(weak_prev);
            } else {
                // Corrupt/back-link missing
                self.head = None;
                self.tail = None;
            }
        } else {
            // This was the only node
            self.head = None;
        }

        // `tail_rc` dropped here; node freed if no other refs exist
        Some(value)
    }

    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            let node = node_rc.borrow();
            print!("{} ", node.value);
            current = node.next.clone();
        }
        println!();
    }
}

fn main() {
    let mut list = List::new();
    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Forward:");
    list.print_forward(); // 10 20 30

    println!("Popped: {:?}", list.pop_back()); // Some(30)
    list.print_forward(); // 10 20
}
```

### Why this avoids your borrow-checker nightmare

| Approach | What it solves |
|----------|---------------|
| `Rc<RefCell<Node>>` | Multiple nodes can "point" to the same data, and you can mutate through the `RefCell` at runtime. |
| `Weak<...>` for `prev` | Prevents reference cycles (`A -> B -> A` keeping both alive forever). The backward link doesn't keep the previous node alive. |
| `borrow_mut()` / `borrow()` | These happen at runtime inside the `RefCell`, so the compiler doesn't need complex lifetime annotations across the graph edges. |

