use std::cell::RefCell;
use std::rc::Rc;

// No lifetimes needed! The edges are owned via Rc.
pub struct Node {
    pub value: i32,
    pub next: Option<Rc<RefCell<Node>>>,
    pub prev: Option<Rc<RefCell<Node>>>,
}

impl Node {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

/// Link two nodes together bidirectionally.
pub fn link_nodes(a: &Rc<RefCell<Node>>, b: &Rc<RefCell<Node>>) {
    // Separate, temporary borrows—no overlap.
    a.borrow_mut().next = Some(Rc::clone(b));
    b.borrow_mut().prev = Some(Rc::clone(a));
}

/// Insert a new node after `left`, correctly rewiring the old next node if present.
pub fn insert_after(
    left: &Rc<RefCell<Node>>,
    new_node: &Rc<RefCell<Node>>,
) {
    // Capture the old next pointer without holding a borrow.
    let old_next = left.borrow().next.clone();

    // Wire left -> new_node.
    left.borrow_mut().next = Some(Rc::clone(new_node));
    new_node.borrow_mut().prev = Some(Rc::clone(left));

    // Wire new_node -> old_next (if there was one).
    if let Some(old) = old_next {
        new_node.borrow_mut().next = Some(Rc::clone(&old));
        old.borrow_mut().prev = Some(Rc::clone(new_node));
    }
}

fn main() {
    // Create nodes.
    let head = Node::new(1);
    let middle = Node::new(2);
    let tail = Node::new(3);

    // Build list: 1 <-> 2 <-> 3
    link_nodes(&head, &middle);
    link_nodes(&middle, &tail);

    // Safe mutation: we hold an Rc (shared pointer), borrow_mut is temporary.
    head.borrow_mut().value = 100;
    middle.borrow_mut().value = 200;

    // Insert 99 between 1 and 2: 1 <-> 99 <-> 2 <-> 3
    let inserted = Node::new(99);
    insert_after(&head, &inserted);

    // Traverse safely.
    // We clone the Rc at each step so the borrow is dropped immediately.
    let mut current: Option<Rc<RefCell<Node>>> = Some(Rc::clone(&head));
    while let Some(node_rc) = current {
        let val = node_rc.borrow().value;
        println!("Node value: {}", val);

        // Clone the next pointer; the borrow of node_rc is released right after.
        current = node_rc.borrow().next.clone();
    }

    // Verify insertion rewired correctly.
    println!("Head next should be 99: {}", head.borrow().next.as_ref().unwrap().borrow().value);
    println!("Tail prev should be 2: {}", tail.borrow().prev.as_ref().unwrap().borrow().value);
}
```

