### The Code

```rust
use std::cell::RefCell;
use std::rc::Rc;

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Rc<RefCell<Node>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        DoublyLinkedList { head: None, tail: None }
    }

    /// Append to the end while maintaining the back-reference.
    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: self.tail.clone(), // back-link to current tail
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Mutate the old tail's forward link
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
            }
            None => {
                // List was empty; new node is also the head
                self.head = Some(Rc::clone(&new_node));
            }
        }

        self.tail = Some(new_node);
    }

    /// Prepend to the front while maintaining the back-reference.
    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: self.head.clone(), // forward link to old head
            prev: None,
        }));

        match self.head.take() {
            Some(old_head) => {
                old_head.borrow_mut().prev = Some(Rc::clone(&new_node));
            }
            None => {
                self.tail = Some(Rc::clone(&new_node));
            }
        }

        self.head = Some(new_node);
    }

    /// Remove from the end. Safe mutation through cloned Rcs avoids borrow conflicts.
    pub fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|old_tail| {
            // Clone the back-link out *before* we borrow mutably elsewhere
            let prev = old_tail.borrow().prev.clone();
            let val = old_tail.borrow().value;

            if let Some(prev_rc) = prev {
                prev_rc.borrow_mut().next = None;
                self.tail = Some(prev_rc);
            } else {
                self.head = None;
            }

            val
        })
    }

    pub fn traverse_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            let node = node_rc.borrow();
            print!("{} ", node.value);
            // Clone the Rc for the next iteration; borrow ends after this line
            current = node.next.clone();
        }
        println!();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_front(5);

    println!("Forward:");
    list.traverse_forward(); // 5 10 20

    if let Some(v) = list.pop_back() {
        println!("Popped: {}", v); // 20
    }

    println!("After pop:");
    list.traverse_forward(); // 5 10
}
```

### Why this avoids your lifetime errors

| Pattern | What it does | Why it fixes your problem |
|---------|-------------|---------------------------|
| `Rc<RefCell<Node>>` | Shared, heap-allocated ownership (`Rc`) + runtime borrow tracking (`RefCell`) | You never write `&'a Node` or `struct Node<'a>`. References are owned pointers, not borrowed references with lifetimes. |
| `borrow()` / `borrow_mut()` | Runtime-checked immutable/mutable borrows | The compiler doesn’t need to prove exclusivity ahead of time. It panics at runtime only if you try a double mutable borrow (e.g., holding a `borrow_mut()` while calling another). |
| Cloning `Option<Rc<...>>` before mutation | In `pop_back`, we clone the `prev` pointer out, then borrow the previous node separately | Keeps borrows on different nodes separate, preventing overlapping mutable borrows. |

