use std::rc::Rc;

struct Graph {
    nodes: Vec<Rc<RefCell<Node>>>,
}

struct Node {
    id: String,
    value: i32,
    // References to other nodes — no lifetimes!
    neighbors: Vec<Rc<RefCell<Node>>>,
}

impl Graph {
