    fn add_edge(&self, from: Rc<RefCell<Node>>, to: Rc<RefCell<Node>>) {
        from.borrow_mut().neighbors.push(to);
    }

    /// Mutate a node's value through its reference.
    fn update_value(&self, node: Rc<RefCell<Node>>, new_value: i32) {
        node.borrow_mut().value = new_value;
    }
}

