use std::rc::Rc;

// ------------------------------------------------------------------
// Doubly-Linked List: shared, mutable nodes
// ------------------------------------------------------------------
type Link = Option<Rc<RefCell<Node>>>;

pub struct Node {
    pub value: i32,
    pub next: Link,
    pub prev: Link,
}

impl Node {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
