impl DoublyLinkedList {
    pub fn new() -> Self {
        Self { head: None }
    }

    /// Push to the front. Returns an `Rc` handle you can keep and mutate later.
    pub fn push_front(&mut self, value: i32) -> Rc<RefCell<Node>> {
        let new_node = Node::new(value);
        match self.head.take() {
            Some(old_head) => {
