        let value = old_head.borrow().value;

        // Break the old head's forward link
        let next = old_head.borrow_mut().next.take();

        if let Some(new_head) = next {
            new_head.borrow_mut().prev = None;
            self.head = Some(new_head);
        } else {
            self.head = None;
        }

        Some(value)
    }

