use std::cell::RefCell;

pub struct Graph {
    nodes: Vec<RefCell<Node>>,
}

pub struct Node {
    pub id: usize,
    pub value: String,
    pub edges: Vec<usize>, // "References" are just indices
}

impl Graph {
    pub fn new() -> Self {
        Graph { nodes: Vec::new() }
    }

    pub fn add_node(&mut self, value: String) -> usize {
        let id = self.nodes.len();
        self.nodes.push(RefCell::new(Node {
            id,
            value,
            edges: Vec::new(),
        }));
        id
    }

    pub fn add_edge(&mut self, from: usize, to: usize) {
        assert!(from < self.nodes.len(), "from out of bounds");
        assert!(to < self.nodes.len(), "to out of bounds");
        // Mutate one node at a time—no borrow checker conflicts
        self.nodes[from].borrow_mut().edges.push(to);
    }

    pub fn add_bidirectional_edge(&mut self, a: usize, b: usize) {
        assert!(a < self.nodes.len() && b < self.nodes.len());
        self.nodes[a].borrow_mut().edges.push(b);
        self.nodes[b].borrow_mut().edges.push(a);
    }

    pub fn get_value(&self, id: usize) -> String {
        self.nodes[id].borrow().value.clone()
    }

    pub fn neighbors(&self, id: usize) -> Vec<usize> {
        self.nodes[id].borrow().edges.clone()
    }
}

fn main() {
    let mut g = Graph::new();
    let a = g.add_node("A".into());
    let b = g.add_node("B".into());
    let c = g.add_node("C".into());

    g.add_bidirectional_edge(a, b);
    g.add_edge(b, c);

    println!("{} -> {:?}", g.get_value(b), g.neighbors(b));
}
```

**Why this works:** There are no `&` references between nodes—only `usize` IDs. The borrow checker is happy because each `borrow_mut()` is isolated to one `Vec` element.

