```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

pub struct DList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

struct Node {
    value: i32,
    prev: Option<Weak<RefCell<Node>>>,
    next: Option<Rc<RefCell<Node>>>,
}

impl DList {
    pub fn new() -> Self {
        DList { head: None, tail: None }
    }

    pub fn push_back(&mut self, val: i32) {
        // 1. Capture current tail as Weak (prevents cycles)
        let prev_weak = self.tail.as_ref().map(|t| Rc::downgrade(t));

        // 2. Create new node
        let node = Rc::new(RefCell::new(Node {
            value: val,
            prev: prev_weak,
            next: None,
        }));

        // 3. Link old tail -> new node
        if let Some(old_tail) = self.tail.take() {
            old_tail.borrow_mut().next = Some(node.clone());
        } else {
            // List was empty
            self.head = Some(node.clone());
        }

        // 4. Update tail
        self.tail = Some(node);
    }

    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(n) = current {
            print!("{} ", n.borrow().value);
            current = n.borrow().next.clone();
        }
        println!();
    }

    pub fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|tail_rc| {
            let val = tail_rc.borrow().value;

            // Read prev before we drop tail_rc
            let prev_weak: Option<Weak<RefCell<Node>>> = tail_rc.borrow().prev.clone();

            if let Some(prev_rc) = prev_weak.and_then(|w| w.upgrade()) {
                prev_rc.borrow_mut().next = None;
                self.tail = Some(prev_rc);
            } else {
                // We removed the only element
                self.head = None;
            }
            val
        })
    }
}

fn main() {
    let mut list = DList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_back(30);
    list.print_forward(); // 10 20 30

    println!("Popped: {:?}", list.pop_back()); // Some(30)
    list.print_forward(); // 10 20
}
```

**The catch:** This uses **runtime** borrow checking. If you ever hold a `borrow()` and try to `borrow_mut()` the same `Rc` (or through a cycle), you get a panic at runtime—not a compile error. That "messy logic" you mentioned is usually people fighting these runtime borrow rules.

