    let mut g = Graph::new();
    let a = g.add_node("A".into());
    let b = g.add_node("B".into());
    let c = g.add_node("C".into());

    g.add_bidirectional_edge(a, b);
    g.add_edge(b, c);

    println!("{} -> {:?}", g.get_value(b), g.neighbors(b));
}
