use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node that can be reached from multiple directions.
/// `prev` is a `Weak` pointer so the list doesn't create a reference cycle.
struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

impl Node {
    fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl DoublyLinkedList {
    fn new() -> Self {
        DoublyLinkedList {
            head: None,
            tail: None,
        }
    }

    /// Append a node. This mutates the old tail and sets up the back-link.
    fn push_back(&mut self, value: i32) {
        let new_node = Node::new(value);

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(new_node.clone());
                // Link new node <- old tail (weak so cycles don't form)
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));

                self.tail = Some(new_node);
            }
            None => {
                // Empty list: new node is both head and tail
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
    }

    /// Remove and return the tail value. Mutates the previous node's `next`.
    fn pop_back(&mut self) -> Option<i32> {
        // Take ownership of the tail Rc out of the list
        self.tail.take().map(|old_tail| {
            // Read the value first (immutable borrow, dropped immediately)
            let value = old_tail.borrow().value;

            // Take the weak back-link out of the old tail
            let prev = old_tail.borrow_mut().prev.take();

            match prev {
                Some(weak_prev) => {
                    if let Some(strong_prev) = weak_prev.upgrade() {
                        // Unlink the previous node
                        strong_prev.borrow_mut().next = None;
                        self.tail = Some(strong_prev);
                    } else {
                        // Previous node was dropped elsewhere; list is broken
                        self.tail = None;
                        self.head = None;
                    }
                }
                None => {
                    // This was the only node
                    self.head = None;
                    // self.tail is already None from `.take()`
                }
            }

            value // old_tail drops here, freeing the node if no other refs exist
        })
    }

    fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node) = current {
            print!("{} ", node.borrow().value);
            current = node.borrow().next.clone();
        }
        println!();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Forward:");
    list.print_forward(); // 10 20 30

    // Mutate via references safely
    if let Some(tail) = list.tail.as_ref() {
        tail.borrow_mut().value += 100;
    }

    println!("After mutation:");
    list.print_forward(); // 10 20 130

    let popped = list.pop_back();
    println!("Popped: {:?}", popped); // Some(130)
    list.print_forward();           // 10 20
}
```

