use std::cell::RefCell;
use std::rc::Rc;

pub struct Node {
    id: usize,
    label: String,
    edges: Vec<Rc<RefCell<Node>>>, // shared, mutable references to other nodes
}

impl Node {
    /// Create a new node wrapped in Rc<RefCell>.
    pub fn new(id: usize, label: impl Into<String>) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            id,
            label: label.into(),
            edges: Vec::new(),
        }))
    }

    /// Connect two nodes bidirectionally.
    pub fn connect(a: Rc<RefCell<Node>>, b: Rc<RefCell<Node>>) {
        // Scope 1: borrow 'a' mutably, clone Rc to 'b'
        {
            let mut a_mut = a.borrow_mut();
            if !a_mut.edges.iter().any(|e| Rc::ptr_eq(e, &b)) {
                a_mut.edges.push(Rc::clone(&b));
            }
        }

        // Scope 2: borrow 'b' mutably, clone Rc to 'a'
        // This avoids holding two borrows on different cells in the same expression,
        // and guarantees we don't accidentally borrow the same cell twice.
        {
            let mut b_mut = b.borrow_mut();
            if !b_mut.edges.iter().any(|e| Rc::ptr_eq(e, &a)) {
                b_mut.edges.push(Rc::clone(&a));
            }
        }
    }

    /// Disconnect two nodes.
    pub fn disconnect(a: Rc<RefCell<Node>>, b: Rc<RefCell<Node>>) {
        let b_id = b.borrow().id; // temporary immutable borrow
        {
            let mut a_mut = a.borrow_mut();
            a_mut.edges.retain(|e| e.borrow().id != b_id);
        }

        let a_id = a.borrow().id; // temporary immutable borrow
        {
            let mut b_mut = b.borrow_mut();
            b_mut.edges.retain(|e| e.borrow().id != a_id);
        }
