use std::cell::RefCell;
use std::rc::{Rc, Weak};

// ------------------------------------------------------------------
// Node definition: uses Rc for shared ownership and RefCell so we can
// mutate value/links through shared references.
// ------------------------------------------------------------------
pub struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>, // Weak avoids reference cycles
}

impl Node {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

// ------------------------------------------------------------------
// The list wrapper keeps head (Rc) and tail (Weak) so we can append
// at both ends and traverse safely.
// ------------------------------------------------------------------
pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Weak<RefCell<Node>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        DoublyLinkedList {
            head: None,
            tail: None,
        }
    }

    // Push to the back. We upgrade the Weak tail, link both directions,
    // and keep the new Weak tail. No lifetime annotations needed.
    pub fn push_back(&mut self, value: i32) {
        let new_node = Node::new(value);

        match self.tail.take() {
            Some(old_tail_weak) => {
                // Upgrade Weak -> Rc. If the old tail was dropped, panic.
                let old_tail = old_tail_weak
                    .upgrade()
                    .expect("Tail was unexpectedly dropped");

                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
                // Link new node <- old tail
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));

                // Update list tail (as Weak to avoid cycles)
                self.tail = Some(Rc::downgrade(&new_node));
            }
            None => {
                // List was empty
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(Rc::downgrade(&new_node));
            }
        }
    }

    // Demonstrate mutation: we borrow each node mutably through the
    // shared Rc, then drop the borrow before moving to the next node.
    pub fn increment_all(&self) {
        let mut current = self.head.clone();
        while let Some(node) = current {
            // Mutate safely
            node.borrow_mut().value += 1;

            // Move to next. The mutable borrow above is dropped at the
            // end of the statement, so this immutable borrow is legal.
            current = node.borrow().next.clone();
        }
    }

    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node) = current {
            // Separate borrows so they don't overlap in the same expression
            let val = node.borrow().value;
            print!("{} ", val);
            current = node.borrow().next.clone();
        }
        println!();
    }

    // Access a node by value to show mutation through a shared reference
    pub fn update_head_value(&self, val: i32) {
        if let Some(ref node) = self.head {
            node.borrow_mut().value = val;
        }
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Initial:");
    list.print_forward();

    // Safe mutation through shared references (no &mut required!)
    list.increment_all();
    println!("After increment_all:");
    list.print_forward();

    // Direct mutation through Rc<RefCell>
    list.update_head_value(99);
    println!("After updating head to 99:");
    list.print_forward();
}
```

### Why this eliminates your borrow-checker pain

| Approach | Problem | Solution here |
|---|---|---|
| Raw references (`&` / `&mut`) | Circular references = impossible lifetimes | Replaced with `Rc` (shared ownership, no lifetimes) |
| Mutation through shared refs | `Rc<T>` is immutable by default | Wrapped in `RefCell<T>` for runtime-checked interior mutability |
| Back-pointers (`prev`) | `Rc` cycles leak memory | Used `Weak` for `prev`; `Weak` doesn't keep the node alive |
| Overlapping borrows | `borrow_mut()` panics at runtime if misused | We drop each borrow before taking the next (`node.borrow_mut()` ends before `node.borrow()`) |

