```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

// ------------------------------------------------------------------
// Data structures: no lifetime parameters needed
// ------------------------------------------------------------------
pub struct List {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

pub struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>, // Weak avoids reference cycles
}

impl List {
    pub fn new() -> Self {
        List { head: None, tail: None }
    }

    // ------------------------------------------------------------------
    // Mutation: we borrow the RefCells at runtime, not compile time
    // ------------------------------------------------------------------
    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(new_node.clone());
                // Link new node <- old tail (Weak so we don't leak memory)
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));

                self.tail = Some(new_node);
            }
            None => {
                // First node
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
    }

    pub fn pop_back(&mut self) -> Option<i32> {
        let old_tail = self.tail.take()?;

        // Separate borrows: first read value, then read prev pointer
        let value = old_tail.borrow().value;
        let prev_weak: Option<Weak<RefCell<Node>>> = old_tail.borrow().prev.clone();

        if let Some(weak) = prev_weak {
            if let Some(prev_rc) = weak.upgrade() {
                prev_rc.borrow_mut().next = None;
                self.tail = Some(prev_rc);
            }
        } else {
            // We just removed the only node
            self.head = None;
        }

        Some(value)
    }

    // ------------------------------------------------------------------
    // Safe traversal: we clone the Rc (increments count), then borrow
    // ------------------------------------------------------------------
    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        print!("Forward: ");
        while let Some(node_rc) = current {
            let val = node_rc.borrow().value;
            print!("{} ", val);
            current = node_rc.borrow().next.clone();
        }
        println!();
    }

    pub fn print_backward(&self) {
        let mut current = self.tail.clone();
        print!("Backward: ");
        while let Some(node_rc) = current {
            let val = node_rc.borrow().value;
            print!("{} ", val);
            let prev_weak = node_rc.borrow().prev.clone();
            current = prev_weak.and_then(|w| w.upgrade());
        }
        println!();
    }
}

