    pub fn add_edge(from: &Rc<RefCell<GraphNode>>, to: Rc<RefCell<GraphNode>>) {
        from.borrow_mut().edges.push(to);
    }

    /// Mutate internal state safely
    pub fn set_data(node: &Rc<RefCell<GraphNode>>, value: impl Into<String>) {
        node.borrow_mut().data = value.into();
    }

    /// Read internal state safely
    pub fn get_data(node: &Rc<RefCell<GraphNode>>) -> String {
        node.borrow().data.clone()
    }

