    let a = GraphNode::new(1, "Alpha");
    let b = GraphNode::new(2, "Beta");
    let c = GraphNode::new(3, "Gamma");

    // 2. Wire the graph: A -> B, B -> C, A -> C
    GraphNode::add_edge(&a, Rc::clone(&b));
    GraphNode::add_edge(&b, Rc::clone(&c));
    GraphNode::add_edge(&a, Rc::clone(&c));

    // 3. Mutate a node that is referenced by others
