use std::fmt;

/// Arena-based node. References are stable indices.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ListNode {
    pub data: i32,
    // References to other nodes by arena index
    pub prev: Option<usize>,
    pub next: Option<usize>,
}

/// A doubly-linked list that lives in an arena.
/// Mutating nodes never invalidates other references because
/// references are indices, not pointers.
pub struct DoublyLinkedList {
    arena: Vec<ListNode>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self {
            arena: Vec::new(),
            head: None,
            tail: None,
        }
    }

    /// Push a value and return the stable index (reference) to it.
    pub fn push_back(&mut self, data: i32) -> usize {
        let idx = self.arena.len();
        let new_node = ListNode {
            data,
            prev: self.tail,
            next: None,
        };
        self.arena.push(new_node);

        if let Some(tail_idx) = self.tail {
            // Update previous tail to point to new node
            self.arena[tail_idx].next = Some(idx);
        } else {
            self.head = Some(idx);
        }
        self.tail = Some(idx);

        idx
    }

    /// Get an immutable reference by index.
    pub fn get(&self, idx: usize) -> Option<&ListNode> {
        self.arena.get(idx)
    }

    /// Get a mutable reference by index. This is safe because
    /// the borrow checker only cares about borrowing `self`
    /// mutably here, not about inter-node references.
    pub fn get_mut(&mut self, idx: usize) -> Option<&mut ListNode> {
        self.arena.get_mut(idx)
    }

    /// Remove a node by index. Updates neighbors automatically.
    /// Returns the data that was stored.
    /// Note: This does not shrink the arena; indices remain stable.
    pub fn remove(&mut self, idx: usize) -> Option<i32> {
        // 1. Copy out links and data to avoid holding borrows.
        let (prev, next, data) = self.arena.get(idx).map(|n| {
            (n.prev, n.next, n.data)
        })?;

        // 2. Update previous node's next pointer.
        if let Some(p) = prev {
            if let Some(node) = self.arena.get_mut(p) {
                node.next = next;
            }
        }

        // 3. Update next node's prev pointer.
        if let Some(n) = next {
            if let Some(node) = self.arena.get_mut(n) {
                node.prev = prev;
            }
        }

        // 4. Update head/tail if necessary.
        if self.head == Some(idx) {
            self.head = next;
        }
        if self.tail == Some(idx) {
            self.tail = prev;
        }

        // 5. Unlink the removed node.
        if let Some(node) = self.arena.get_mut(idx) {
            node.prev = None;
            node.next = None;
            // We leave the data in place but return a copy.
            // (In a real system you might use Option<i32> to take ownership.)
        }

        Some(data)
    }

    pub fn len(&self) -> usize {
        self.arena.len()
    }

    pub fn is_empty(&self) -> bool {
        self.arena.is_empty()
    }
}

