// Arena-based Doubly-Linked List
// Uses usize indices instead of references, eliminating lifetime and borrow issues.
// All mutations happen through the arena container, not through borrowed node refs.

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq)]
struct NodeId(usize);

struct Node {
    value: i32,
    prev: Option<NodeId>,
    next: Option<NodeId>,
}

pub struct DoublyLinkedList {
    arena: Vec<Node>,
    head: Option<NodeId>,
    tail: Option<NodeId>,
    // Optional: free list for reuse, omitted for simplicity
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self {
            arena: Vec::new(),
            head: None,
            tail: None,
        }
    }

    /// Push a value to the back. Returns its stable NodeId.
    pub fn push_back(&mut self, value: i32) -> NodeId {
        let id = NodeId(self.arena.len());
        let prev = self.tail;

        let new_node = Node {
            value,
            prev,
            next: None,
        };

        // Link previous tail to this new node
        if let Some(tail_id) = self.tail {
            if tail_id.0 < self.arena.len() {
                self.arena[tail_id.0].next = Some(id);
            }
        }

        self.arena.push(new_node);
        self.tail = Some(id);

        if self.head.is_none() {
            self.head = Some(id);
        }

        id
    }

    /// Insert a new node after the given id.
    pub fn insert_after(&mut self, after: NodeId, value: i32) -> Option<NodeId> {
        if after.0 >= self.arena.len() {
            return None;
        }

        let new_id = NodeId(self.arena.len());
        let next_id = self.arena[after.0].next;

        let mut new_node = Node {
            value,
            prev: Some(after),
            next: next_id,
        };

        // Link the 'after' node forward to us
        self.arena[after.0].next = Some(new_id);

        // Link the next node backward to us
        if let Some(n) = next_id {
            if n.0 < self.arena.len() {
                self.arena[n.0].prev = Some(new_id);
            }
        } else {
            // We are now the tail
            self.tail = Some(new_id);
        }

        self.arena.push(new_node);
        Some(new_id)
    }

    /// Remove and return the value at the given id.
    /// Note: this does NOT shrink the arena; the slot is left empty (tombstoned implicitly by being unreachable).
    pub fn remove(&mut self, id: NodeId) -> Option<i32> {
        if id.0 >= self.arena.len() {
            return None;
        }

        // Copy all needed data out of the borrow scope
        let prev_id = self.arena[id.0].prev;
        let next_id = self.arena[id.0].next;
        let value = self.arena[id.0].value;

        // Unlink previous node
        if let Some(p) = prev_id {
            if p.0 < self.arena.len() {
                self.arena[p.0].next = next_id;
            }
        } else {
            // We were the head
            self.head = next_id;
        }

        // Unlink next node
        if let Some(n) = next_id {
            if n.0 < self.arena.len() {
                self.arena[n.0].prev = prev_id;
            }
        } else {
            // We were the tail
            self.tail = prev_id;
        }

        Some(value)
    }

    /// Access value immutably.
    pub fn get(&self, id: NodeId) -> Option<i32> {
        self.arena.get(id.0).map(|n| n.value)
    }

    /// Update a node's value in place.
    pub fn update_value(&mut self, id: NodeId, value: i32) -> bool {
        if let Some(node) = self.arena.get_mut(id.0) {
            node.value = value;
            true
        } else {
            false
        }
    }

    /// Print the list in order.
    pub fn display(&self) {
        print!("List: ");
        let mut current = self.head;
        while let Some(id) = current {
            if let Some(node) = self.arena.get(id.0) {
                print!("{} ", node.value);
                current = node.next;
            } else {
                break;
            }
        }
        println!();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    // Build: 10 <-> 20
    let a = list.push_back(10);
    let b = list.push_back(20);
    list.display(); // 10 20

    // Insert 15 after 10: 10 <-> 15 <-> 20
    list.insert_after(a, 15);
    list.display();

    // Mutate the middle node safely
    list.update_value(a, 100);
    list.display(); // 100 15 20

    // Remove the tail (20)
    list.remove(b);
    list.display(); // 100 15

    // Remove head
    list.remove(a);
    list.display(); // 15
}

impl fmt::Display for DoublyLinkedList {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut s = String::new();
        let mut current = self.head;
        while let Some(id) = current {
            if let Some(node) = self.arena.get(id.0) {
                s.push_str(&format!("{} ", node.value));
                current = node.next;
            } else {
                break;
            }
        }
        write!(f, "DoublyLinkedList [{} nodes]", s.trim())
    }
}
