/// A robust, borrow-checker-friendly graph using indices.
pub struct Graph {
    nodes: Vec<Node>,
}

pub struct Node {
    pub id: usize,
    pub data: String,
    pub edges: Vec<usize>, // indices of target nodes
}

impl Graph {
    pub fn new() -> Self {
        Graph { nodes: Vec::new() }
    }

    /// Add a node and return its stable index.
    pub fn add_node(&mut self, data: String) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            id,
            data,
            edges: Vec::new(),
        });
        id
    }

    /// Add a directed edge.
    pub fn add_edge(&mut self, from: usize, to: usize) {
        assert!(from < self.nodes.len(), "Source node out of bounds");
        assert!(to < self.nodes.len(), "Target node out of bounds");
        if !self.nodes[from].edges.contains(&to) {
            self.nodes[from].edges.push(to);
        }
    }

    /// Mutate a node safely. No lifetimes, no Rc, no RefCell.
    pub fn mutate_node<F>(&mut self, id: usize, mut f: F)
    where
        F: FnMut(&mut Node),
    {
        assert!(id < self.nodes.len());
        f(&mut self.nodes[id]);
    }

    /// Read neighbors for traversal.
    pub fn neighbors(&self, id: usize) -> &[usize] {
        &self.nodes[id].edges
    }

    /// Get immutable reference to node data.
    pub fn get(&self, id: usize) -> Option<&Node> {
        self.nodes.get(id)
    }

    /// Get mutable reference.
    pub fn get_mut(&mut self, id: usize) -> Option<&mut Node> {
        self.nodes.get_mut(id)
    }
}
