### 1. Doubly-Linked List (`Rc` + `RefCell` + `Weak`)

This avoids cycles (memory leaks) by making `prev` a `Weak` pointer, while `next` stays `Rc`. You can mutate any node through shared references.

```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>, // Weak = no cycle
}

impl Node {
    fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl DoublyLinkedList {
    fn new() -> Self {
        Self { head: None, tail: None }
    }

    fn push_back(&mut self, value: i32) {
        let node = Node::new(value);
        match self.tail.take() {
            Some(old_tail) => {
                old_tail.borrow_mut().next = Some(node.clone());
                node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                self.tail = Some(node);
            }
            None => {
                self.head = Some(node.clone());
                self.tail = Some(node);
            }
        }
    }

    fn push_front(&mut self, value: i32) {
        let node = Node::new(value);
        match self.head.take() {
            Some(old_head) => {
                old_head.borrow_mut().prev = Some(Rc::downgrade(&node));
                node.borrow_mut().next = Some(old_head);
                self.head = Some(node);
            }
            None => {
                self.head = Some(node.clone());
                self.tail = Some(node);
            }
        }
    }

    fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|old_tail| {
            let value = old_tail.borrow().value;
            let prev_weak = old_tail.borrow().prev.clone(); // clone Weak, drop borrow

            if let Some(w) = prev_weak {
                if let Some(prev) = w.upgrade() {
                    prev.borrow_mut().next = None;
                    self.tail = Some(prev);
                } else {
                    self.head = None;
                    self.tail = None;
                }
            } else {
                self.head = None;
                self.tail = None;
            }
            value
        })
    }

    fn print_forward(&self) {
        let mut cur = self.head.clone();
        while let Some(n) = cur {
            print!("{} ", n.borrow().value);
            cur = n.borrow().next.clone();
        }
        println!();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_front(5);
    list.print_forward(); // 5 10 20

    println!("Popped: {:?}", list.pop_back()); // Some(20)
    list.print_forward(); // 5 10
}
```

**Why this works:**
- `Rc<RefCell<Node>>` lets multiple nodes “own” references and mutate via `.borrow_mut()`.
- `Weak` breaks the back-reference cycle so `pop_back` can drop cleanly.
- No `&mut` borrow of the list conflicts with internal node borrows because `RefCell` checks borrows at **runtime**, not compile time.

