use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node in the list. No lifetime annotations needed.
pub struct Node {
    value: i32,
    prev: Option<Weak<RefCell<Node>>>, // Weak breaks the cycle
    next: Option<Rc<RefCell<Node>>>,    // Strong forward link
