            self.tail = None;
        }

        // `head` Rc is dropped here; since prev/next are now None/Weak,
        // and previous node holds only a Weak pointer, the node is freed.
        Some(value)
    }

    /// Traverse without consuming.
    pub fn traverse(&self, mut f: impl FnMut(i32)) {
        let mut current = self.head.clone();
        while let Some(node) = current {
            let val = node.borrow().value;
            f(val);
            current = node.borrow().next.clone();
        }
    }

