### Pattern A: Arena Graph (Recommended — Zero Lifetimes)

This uses an index-based adjacency list. Because references are numbers (`usize`), you can mutate nodes freely without overlapping borrows.

```rust
use std::fmt;

#[derive(Debug, Default, Clone)]
pub struct Node {
    pub id: usize,
    pub label: String,
    pub neighbors: Vec<usize>, // references are just indices
}

pub struct Graph {
    nodes: Vec<Node>,
}

impl Graph {
    pub fn new() -> Self {
        Graph { nodes: Vec::new() }
    }

    /// Create a node and return its index (the "reference").
    pub fn add_node(&mut self, label: impl Into<String>) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            id,
            label: label.into(),
            neighbors: Vec::new(),
        });
        id
    }

    /// Link two nodes. The borrows are brief and non-overlapping.
    pub fn link(&mut self, a: usize, b: usize) {
        assert!(a < self.nodes.len(), "bad index {}", a);
        assert!(b < self.nodes.len(), "bad index {}", b);
        if a == b { return; }

        // Each statement borrows the Vec briefly, then releases it.
        if !self.nodes[a].neighbors.contains(&b) {
            self.nodes[a].neighbors.push(b);
        }
        if !self.nodes[b].neighbors.contains(&a) {
            self.nodes[b].neighbors.push(a);
        }
    }

    /// Mutate two connected nodes without lifetime errors.
    /// We clone the data we need, then write—no long-lived `&mut` conflicts.
    pub fn copy_label(&mut self, from: usize, to: usize) {
        let source = self.nodes[from].label.clone();
        self.nodes[to].label = source;
    }

    pub fn get(&self, id: usize) -> Option<&Node> {
        self.nodes.get(id)
    }

    pub fn print(&self) {
        for n in &self.nodes {
            println!("{} [{}] -> {:?}", n.id, n.label, n.neighbors);
        }
    }
}

fn main() {
    let mut g = Graph::new();
    let a = g.add_node("A");
    let b = g.add_node("B");
    let c = g.add_node("C");

    g.link(a, b);
    g.link(b, c);

    // This is the kind of "mutate through references" logic that usually fails
    // with lifetimes. Here it's just index arithmetic.
    g.copy_label(b, a);

    g.print();
}
```

