use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct Node {
    id: usize,
    label: String,
    // Weak prevents reference cycles; edges don't keep targets alive
    edges: RefCell<Vec<Weak<RefCell<Node>>>>,
}

impl Node {
    /// Factory: returns an Rc so we can share it.
    pub fn new(id: usize, label: impl Into<String>) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            id,
            label: label.into(),
            edges: RefCell::new(Vec::new()),
        }))
    }

    /// Add a directed edge: this node -> target
    pub fn link(
        source: &Rc<RefCell<Node>>,
        target: &Rc<RefCell<Node>>,
    ) {
        // borrow_mut on the source's inner RefCell
        source.borrow_mut().edges.borrow_mut().push(Rc::downgrade(target));
    }

    /// Read neighbors safely. Returns new strong Rcs for nodes still alive.
    pub fn neighbors(node: &Rc<RefCell<Node>>) -> Vec<Rc<RefCell<Node>>> {
        // borrow() is immutable and brief; we collect owned Rcs and release it immediately
        node.borrow().edges.borrow()
            .iter()
            .filter_map(|w| w.upgrade())
            .collect()
    }

    /// Mutate node data directly
    pub fn set_label(node: &Rc<RefCell<Node>>, label: impl Into<String>) {
        node.borrow_mut().label = label.into();
    }
}

fn main() {
    let a = Node::new(1, "A");
    let b = Node::new(2, "B");
    let c = Node::new(3, "C");

    // Build graph with a cycle: A -> B -> C -> A
    // This is safe because edges are Weak; it won't leak memory.
    Node::link(&a, &b);
    Node::link(&a, &c);
    Node::link(&b, &c);
    Node::link(&c, &a);

    // Mutate safely via shared Rc references
    Node::set_label(&a, "Alpha");

    println!("{} has neighbors:", a.borrow().label);
    for n in Node::neighbors(&a) {
        println!("  -> {} ({})", n.borrow().label, n.borrow().id);
    }

    println!(
        "B's neighbors: {:?}",
        Node::neighbors(&b)
            .iter()
            .map(|n| n.borrow().id)
            .collect::<Vec<_>>()
    );
}
