```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

pub struct DNode {
    pub value: i32,
    pub next: Option<Rc<RefCell<DNode>>>,
    pub prev: Option<Weak<RefCell<DNode>>>,
}

pub struct DList {
    head: Option<Rc<RefCell<DNode>>>,
}

impl DList {
    pub fn new() -> Self {
        Self { head: None }
    }

    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(DNode {
            value,
            next: self.head.take(),
            prev: None,
        }));

        // Link old head back to new node. We clone the Rc pointer,
        // then borrow the old head mutably. These are separate allocations,
        // so the borrow checker (runtime) allows it.
        if let Some(old_head) = new_node.borrow().next.clone() {
            old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
        }

        self.head = Some(new_node);
    }

    pub fn pop_front(&mut self) -> Option<i32> {
        let old_head = self.head.take()?;

        // Extract links without holding borrows across mutations.
        let next: Option<Rc<RefCell<DNode>>> = {
            let borrow = old_head.borrow();
            borrow.next.clone()
        };

        // Break backward link in the new head.
        if let Some(ref new_head) = next {
            new_head.borrow_mut().prev = None;
        }

        // Extract value safely.
        let value = {
            let borrow = old_head.borrow();
            borrow.value
        };

        self.head = next;
        Some(value)
    }

    /// Traverse and collect values (demonstrates safe shared reads).
    pub fn to_vec(&self) -> Vec<i32> {
        let mut result = Vec::new();
        let mut current = self.head.clone();
        while let Some(node) = current {
            let val = node.borrow().value;
            result.push(val);
            current = {
                let borrow = node.borrow();
                borrow.next.clone()
            };
        }
        result
    }
}

fn main() {
    let mut list = DList::new();
    list.push_front(30);
    list.push_front(20);
    list.push_front(10);

    println!("List: {:?}", list.to_vec());

    if let Some(v) = list.pop_front() {
        println!("Popped: {}", v);
    }

    println!("After pop: {:?}", list.to_vec());
}
```

**Key design points that avoid errors:**
- `prev` is `Weak`, not `Rc`, so the list doesn’t create a reference cycle (`A -> B -> A` with strong refs = leak).
- Every `borrow_mut()` is scoped tightly; we never hold an immutable borrow on one node and try to mutably borrow a different node in a conflicting way.
- There are **zero lifetime parameters** (`<'a>`) in the public API because ownership is shared at runtime, not borrowed at compile time.

