use std::rc::{Rc, Weak};

pub struct DNode {
    pub value: i32,
    pub next: Option<Rc<RefCell<DNode>>>,
    pub prev: Option<Weak<RefCell<DNode>>>,
}

pub struct DList {
    head: Option<Rc<RefCell<DNode>>>,
}

impl DList {
    pub fn new() -> Self {
        Self { head: None }
    }

    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(DNode {
            value,
            next: self.head.take(),
            prev: None,
        }));

        if let Some(old_head) = new_node.borrow().next.clone() {
            old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
        }

        self.head = Some(new_node);
    }

    pub fn pop_front(&mut self) -> Option<i32> {
        let old_head = self.head.take()?;

        // Extract next without holding borrow over mutation
        let next = {
            let borrow = old_head.borrow();
            borrow.next.clone()
        };

        // Break backward link in new head
        if let Some(ref new_head) = next {
            new_head.borrow_mut().prev = None;
        }

        // Get value
        let value = {
            let borrow = old_head.borrow();
            borrow.value
        };

        self.head = next;
        Some(value)
