use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node in the doubly-linked list.
/// - `next` is a strong `Rc` so we can traverse forward.
/// - `prev` is a `Weak` reference so we don't create a strong reference cycle
///   (if both directions were `Rc`, nodes would never be freed).
struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        DoublyLinkedList {
            head: None,
            tail: None,
        }
    }

    /// Append a new node. We briefly borrow the old tail and the new node,
    /// but never hold overlapping borrows.
    pub fn push_back(&mut self, value: i32) {
        let node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node (strong reference)
                old_tail.borrow_mut().next = Some(node.clone());
                // Link new node <- old tail (weak reference, avoids cycle)
                node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                self.tail = Some(node);
            }
            None => {
                // List was empty
                self.head = Some(node.clone());
                self.tail = Some(node);
            }
        }
    }

    /// Remove and return the tail value. The borrows are kept short:
    /// 1. Read the value.
    /// 2. Take the weak `prev` link.
    /// 3. Mutate the previous node's `next` (a different `Rc`).
    pub fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|old_tail| {
            // Short immutable borrow to read data
            let value = old_tail.borrow().value;

            // Short mutable borrow to detach the back-link
            let prev_weak = old_tail.borrow_mut().prev.take();

            match prev_weak {
                Some(weak) => {
                    if let Some(prev_rc) = weak.upgrade() {
                        prev_rc.borrow_mut().next = None;
                        self.tail = Some(prev_rc);
                    } else {
                        // Previous node was dropped unexpectedly
                        self.tail = None;
                        self.head = None;
                    }
                }
                None => {
                    // This was the only node in the list
                    self.head = None;
                    self.tail = None;
                }
            }

            // `old_tail` is dropped here, freeing the node if no other refs exist
            value
        })
    }

    /// Print values without holding a borrow across loop iterations.
    pub fn print_forward(&self) {
        let mut curr = self.head.clone();
        while let Some(node_rc) = curr {
            let next_opt = {
                // Borrow is confined to this inner block
                let n = node_rc.borrow();
                print!("{} ", n.value);
                n.next.clone() // clone the Rc pointer, not borrowing the cell
            };
            curr = next_opt;
        }
        println!();
    }

    /// Returns an external `Rc` reference to the head.
    /// This demonstrates "maintaining references" to nodes outside the list.
    pub fn head_ref(&self) -> Option<Rc<RefCell<Node>>> {
        self.head.clone()
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Initial:");
    list.print_forward();

    // SAFELY mutate a node via an external reference.
    // No lifetime annotations needed because `Rc` owns the data.
    if let Some(node) = list.head_ref() {
        node.borrow_mut().value = 99;
    }

    println!("After mutating head via external Rc:");
    list.print_forward();

    // Mutate links (pop_back) while external references could still exist
    list.pop_back();
    println!("After pop_back:");
    list.print_forward();
}
```

