use std::cell::RefCell;
use std::rc::{Rc, Weak};

// ------------------------------------------------------------------
// Node definition: shared, mutable, and can reference other nodes.
// ------------------------------------------------------------------
pub struct ListNode {
    value: i32,
    // Forward link: strong reference (owns the rest of the chain)
    next: Option<Rc<RefCell<ListNode>>>,
    // Backward link: weak reference (does NOT prevent deallocation)
    prev: Option<Weak<RefCell<ListNode>>>,
}

impl ListNode {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(ListNode {
            value,
            next: None,
            prev: None,
        }))
    }
}

// ------------------------------------------------------------------
// List wrapper that maintains head / tail without borrow-checker pain.
// ------------------------------------------------------------------
pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<ListNode>>>,
    tail: Option<Weak<RefCell<ListNode>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        DoublyLinkedList {
            head: None,
            tail: None,
        }
    }

    /// Append to the end. Uses runtime borrows (`borrow_mut`) so we
    /// don't need mutable exclusivity over the whole graph.
    pub fn push_back(&mut self, value: i32) {
        let new_node = ListNode::new(value);

        match self.tail.take() {
            Some(old_weak) => {
                if let Some(old_tail) = old_weak.upgrade() {
                    // Link old tail -> new node
                    old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
                    // Link new node <- old tail (Weak to avoid cycles!)
                    new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                } else {
                    // Previous tail was dropped; reset as fresh list
                    self.head = Some(Rc::clone(&new_node));
                }
            }
            None => {
                // Empty list
                self.head = Some(Rc::clone(&new_node));
            }
        }

        // Update tail pointer to the new end
        self.tail = Some(Rc::downgrade(&new_node));
    }

    /// Traverse and print. Note that `borrow()` is dropped before
    /// moving to the next node, preventing overlapping borrows.
    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            let value = {
                let n = node_rc.borrow();
                n.value
            }; // borrow ends here
            print!("{} ", value);

            current = {
                let n = node_rc.borrow();
                n.next.clone()
            }; // borrow ends here
        }
        println!();
    }

    /// Demonstrates mutation through a shared (`Rc`) reference.
    /// Notice we take `&self`, not `&mut self`, because `RefCell`
    /// handles the mutation at runtime.
    pub fn update_first(&self, value: i32) {
        if let Some(node) = &self.head {
            node.borrow_mut().value = value;
        }
    }
}

// ------------------------------------------------------------------
// Example usage.
// ------------------------------------------------------------------
fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Initial list:");
    list.print_forward(); // 10 20 30

    // Mutate the first node through an immutable list reference
    list.update_first(99);
    println!("After mutation:");
    list.print_forward(); // 99 20 30
}
```

### Why this avoids your lifetime hell

| Pattern | What it solves |
|--------|----------------|
| **`Rc<T>`** | Shared ownership; nodes can live as long as anything references them. No `<'a>` annotations needed on the struct. |
| **`RefCell<T>`** | Interior mutability. You call `.borrow_mut()` to get a temporary mutable reference at **runtime**, sidestepping Rust's compile-time exclusivity rules. |
| **`Weak<T>`** | The `prev` pointer is weak. This breaks reference cycles, so dropping the `head` eventually frees the entire chain (no memory leak). |
| **No `&mut` required on `update_first`** | Because mutation is encapsulated inside the `RefCell`, you can share references (`Rc`) and still modify values safely. |

### Runtime safety note
`RefCell` enforces borrowing rules **at runtime**. If you accidentally call `.borrow_mut()` twice on the same node in an overlapping way, it will `panic!`. This is the trade-off: you avoid compile-time lifetime annotations, but you must ensure borrows don't overlap at execution time.

### Extending to a graph
If you need a true graph instead of a list, replace `next`/`prev` with a `Vec<Rc<RefCell<Node>>>` (adjacency list) inside `RefCell`. The same `Rc`/`Weak` rules apply—use `Weak` for any back-edges you want to prevent from pinning nodes in memory.

