use std::cell::RefCell;
use std::rc::Rc;

#[derive(Debug, Default)]
pub struct Node {
    id: usize,
    label: String,
    out: Vec<Rc<RefCell<Node>>>, // references to other nodes
}

impl Node {
    pub fn new(id: usize, label: impl Into<String>) -> Self {
        Self {
            id,
            label: label.into(),
            out: Vec::new(),
        }
    }

    /// Link this node to another.
    pub fn link(&mut self, target: Rc<RefCell<Node>>) {
        self.out.push(target);
    }

    pub fn label(&self) -> &str {
        &self.label
    }
}

#[derive(Default)]
pub struct Graph {
    nodes: Vec<Rc<RefCell<Node>>>,
}

impl Graph {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_node(&mut self, id: usize, label: impl Into<String>) -> Rc<RefCell<Node>> {
        let n = Rc::new(RefCell::new(Node::new(id, label)));
        self.nodes.push(Rc::clone(&n));
        n
    }

    /// Create a directed edge.
    pub fn link(&self, from: &Rc<RefCell<Node>>, to: &Rc<RefCell<Node>>) {
        from.borrow_mut().link(Rc::clone(to));
    }

    pub fn nodes(&self) -> &[Rc<RefCell<Node>>] {
        &self.nodes
    }
}

fn main() {
    let mut g = Graph::new();
    let a = g.add_node(0, "A");
    let b = g.add_node(1, "B");
    let c = g.add_node(2, "C");

    g.link(&a, &b);
    g.link(&b, &c);
    g.link(&a, &c);

    // Safe mutation: borrow ONE node at a time
    {
        let mut mut_a = a.borrow_mut();
        mut_a.label = "Alpha".to_string();
        // Do NOT try to borrow `b` or `c` through `mut_a.out` here,
        // because `mut_a` already holds an exclusive borrow on `a`.
    }

    // Read-only traversal
    println!("Edges from A:");
    // We borrow `a` immutably for the iterator
    for target_rc in &a.borrow().out {
        let target = target_rc.borrow();
        println!("  -> {}", target.label);
    }

    // If you need to mutate `a` again, do it in a separate scope
    {
        a.borrow_mut().label = "Updated Alpha".to_string();
    }
}
```

**Critical `RefCell` rule shown above:** The `borrow_mut()` in the first block ends before the traversal starts. If you tried to iterate over `a.borrow().out` and inside that loop call `a.borrow_mut()`, the program would **panic at runtime** (not compile-time). The borrow checker allows the code; `RefCell` enforces the exclusivity when it runs.

