        let value = tail_rc.borrow().value;                 // temporary borrow
        let prev_weak = tail_rc.borrow().prev.clone();        // temporary borrow

        match prev_weak {
            Some(weak_prev) => {
                if let Some(strong_prev) = weak_prev.upgrade() {
                    strong_prev.borrow_mut().next = None;   // mutate previous node
                    self.tail = Some(strong_prev);           // move tail back
                }
            }
            None => {
                // This was the only node in the list.
                self.head = None;
            }
        }

        // tail_rc drops here, freeing the removed node.
        Some(value)
    }

