use std::cell::RefCell;
use std::rc::{Rc, Weak};

pub struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

impl Node {
    fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

pub struct List {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl List {
    fn new() -> Self {
        List { head: None, tail: None }
    }

    fn push_back(&mut self, value: i32) {
        let new_node = Node::new(value);
        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(new_node.clone());
                // Link new node <- old tail (weak to break cycle)
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                self.tail = Some(new_node);
            }
            None => {
                // List was empty
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
    }

    fn pop_back(&mut self) -> Option<i32> {
        let tail_rc = self.tail.take()?;

        let value = tail_rc.borrow().value;
        let prev_weak = tail_rc.borrow().prev.clone();

        match prev_weak {
            Some(weak_prev) => {
                if let Some(strong_prev) = weak_prev.upgrade() {
                    strong_prev.borrow_mut().next = None;
                    self.tail = Some(strong_prev);
                }
            }
            None => {
                // This was the only node
                self.head = None;
            }
        }

        Some(value)
    }

    fn len(&self) -> usize {
        let mut count = 0;
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            count += 1;
            current = node_rc.borrow().next.clone();
        }
        count
    }
}

fn main() {
    let mut list = List::new();
    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Length: {}", list.len());

    if let Some(val) = list.pop_back() {
        println!("Popped: {}", val);
    }

    println!("Length after pop: {}", list.len());
}
```

