use std::cell::RefCell;
use std::rc::Rc;

pub type Link = Rc<RefCell<Node>>;

pub struct Node {
    pub id: String,
    pub payload: i32,
    edges: RefCell<Vec<Link>>,
}

impl Node {
    /// Create a new node wrapped in Rc<RefCell<...>>.
    pub fn new(id: impl Into<String>, payload: i32) -> Link {
        Rc::new(RefCell::new(Node {
            id: id.into(),
            payload,
            edges: RefCell::new(Vec::new()),
        }))
    }

    /// Add a directed edge from this node to another.
    /// We clone the Rc pointer—no borrow conflicts.
    pub fn connect(&self, other: &Link) {
        self.edges.borrow_mut().push(Rc::clone(other));
    }

    /// Read-only view of edges.
    pub fn edges_view(&self) -> std::cell::Ref<'_, Vec<Link>> {
        self.edges.borrow()
    }

    /// Describe without recursing into full Debug (avoids cycle issues).
    pub fn describe(&self) {
        println!(
            "Node '{}' (payload={}) -> {} edges",
            self.id,
            self.payload,
            self.edges.borrow().len()
        );
    }
}

/// Mutate a node's payload through any reference you hold.
pub fn set_payload(node: &Link, value: i32) {
    node.borrow_mut().payload = value;
}

/// Rename through any reference.
pub fn rename(node: &Link, new_id: impl Into<String>) {
    node.borrow_mut().id = new_id.into();
}

fn main() {
    // Create nodes
    let a = Node::new("A", 10);
    let b = Node::new("B", 20);
    let c = Node::new("C", 30);

    // Build graph: A -> B, A -> C, B -> C
    a.borrow().connect(&b);
    a.borrow().connect(&c);
    b.borrow().connect(&c);

    println!("Initial state:");
    a.borrow().describe();
    b.borrow().describe();
    c.borrow().describe();

    // Mutate C safely through B's reference (shared ownership in action)
    set_payload(&c, 99);
    rename(&c, "C-Updated");

    // Mutate B through its own Rc
    set_payload(&b, 42);

    println!("\nAfter mutations:");
    println!("A edges:");
    for target in a.borrow().edges_view().iter() {
        let n = target.borrow();
        println!("  -> {} (payload={})", n.id, n.payload);
    }

    // Show that the mutation to C is visible everywhere
    println!("\nC's state: id='{}', payload={}", c.borrow().id, c.borrow().payload);
}
```

