use std::cell::RefCell;
use std::rc::{Rc, Weak};

pub struct Node {
    value: i32,
    prev: Option<Weak<RefCell<Node>>>,
    next: Option<Rc<RefCell<Node>>>,
}

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
    len: usize,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self { head: None, tail: None, len: 0 }
    }

    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Link backward via Weak (breaks cycles)
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));

                // Link forward via Rc
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));

                self.tail = Some(new_node);
            }
            None => {
                // Empty list
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    pub fn pop_back(&mut self) -> Option<i32> {
        let tail_node = self.tail.take()?;

        // Scope 1: read value
        let value = {
            let r = tail_node.borrow();
            r.value
        };

        // Scope 2: read weak prev pointer (separate borrow!)
        let prev_rc = {
            let r = tail_node.borrow();
            r.prev.as_ref().map(|w| w.upgrade())
        };

        if let Some(prev) = prev_rc {
            prev.borrow_mut().next = None;
            self.tail = Some(prev);
        } else {
            // This was the only node
            self.head = None;
        }

        self.len -= 1;
        Some(value)
    }

    pub fn len(&self) -> usize { self.len }
    pub fn is_empty(&self) -> bool { self.len == 0 }

    /// Safe traversal + mutation demonstration
    pub fn increment_all(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            // Scope A: mutate
            {
                let mut n = node_rc.borrow_mut();
                n.value += 1;
            }
            // Scope B: read next (borrow_mut is already dropped!)
            let next = {
                let n = node_rc.borrow();
                n.next.clone()
            };
            current = next;
        }
    }

    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            print!("{} ", node_rc.borrow().value);
            let next = {
                let n = node_rc.borrow();
                n.next.clone()
            };
            current = next;
        }
        println!();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Start:");
    list.print_forward(); // 10 20 30

    list.increment_all();
    println!("After increment:");
    list.print_forward(); // 11 21 31

    println!("Popped: {:?}", list.pop_back());
    list.print_forward(); // 11 21

    list.pop_back();
    list.pop_back();
    println!("Final len: {}", list.len()); // 0
}
```

