use std::cell::RefCell;
use std::rc::{Rc, Weak};

pub struct Node {
    value: i32,
    prev: Option<Weak<RefCell<Node>>>,
    next: Option<Rc<RefCell<Node>>>,
}

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
    len: usize,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));

                // Update list tail
                self.tail = Some(new_node);
            }
            None => {
                // List was empty
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    pub fn pop_back(&mut self) -> Option<i32> {
        let tail_node = self.tail.take()?;

        let value = {
            let r = tail_node.borrow();
            r.value
        };

        let prev_weak = {
            let r = tail_node.borrow();
            r.prev.as_ref().map(|w| w.upgrade())
        };

        if let Some(prev_rc) = prev_weak {
            prev_rc.borrow_mut().next = None;
            self.tail = Some(prev_rc);
        } else {
            // This was the only node
            self.head = None;
        }

        self.len -= 1;
        Some(value)
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn print_forward(&self) {
