            print!("{} ", val);

            // Clone the next pointer before the borrow ends
            let next = {
                let n = node_rc.borrow();
                n.next.clone()
            };
            current = next;
        }
        println!();
    }

    /// Demonstrates safe mutation while traversing
    pub fn increment_all(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            {
                let mut n = node_rc.borrow_mut();
                n.value += 1;
            }
            let next = {
                let n = node_rc.borrow();
                n.next.clone()
            };
            current = next;
        }
    }
}

fn main() {
