```rust
use std::collections::{HashSet, VecDeque};

#[derive(Debug, Clone, Default)]
pub struct NodeData {
    pub value: String,
    pub edges: HashSet<usize>, // references are just indices
}

pub struct Graph {
    nodes: Vec<NodeData>,
}

impl Graph {
    pub fn new() -> Self {
        Self { nodes: Vec::new() }
    }

    /// Returns the index of the new node.
    pub fn add_node(&mut self, value: impl Into<String>) -> usize {
        let id = self.nodes.len();
        self.nodes.push(NodeData {
            value: value.into(),
            edges: HashSet::new(),
        });
        id
    }

    pub fn add_edge(&mut self, a: usize, b: usize) {
        if a < self.nodes.len() && b < self.nodes.len() && a != b {
            self.nodes[a].edges.insert(b);
            self.nodes[b].edges.insert(a); // undirected
        }
    }

    /// Mutate nodes safely without borrowing conflicts.
    /// We clone the neighbor list first so we don't hold a borrow
    /// on `self.nodes` while we borrow other nodes.
    pub fn propagate_mutation(&mut self, start: usize, delta: i32) {
        // Immutable borrow only for this line
        let neighbors: Vec<usize> = self.nodes.get(start)
            .map(|n| n.edges.iter().cloned().collect())
            .unwrap_or_default();

        // Now we can borrow nodes individually and mutate them
        for n in neighbors {
            if let Some(node) = self.nodes.get_mut(n) {
                node.value = format!("{} + {}", node.value, delta);
            }
        }

        // Finally mutate the origin node separately
        if let Some(node) = self.nodes.get_mut(start) {
            node.value.push_str(" [origin]");
        }
    }

    pub fn get_value(&self, id: usize) -> Option<&str> {
        self.nodes.get(id).map(|n| n.value.as_str())
    }

    pub fn len(&self) -> usize {
        self.nodes.len()
    }
}

fn main() {
    let mut g = Graph::new();
    let a = g.add_node("A");
    let b = g.add_node("B");
    let c = g.add_node("C");

    g.add_edge(a, b);
    g.add_edge(b, c);

    g.propagate_mutation(b, 42);

    println!("A = {:?}", g.get_value(a));
    println!("B = {:?}", g.get_value(b));
    println!("C = {:?}", g.get_value(c));
}
```

**Why this avoids your pain:** There are no `&Node` references with lifetimes stored inside `NodeData`. The `Vec<NodeData>` owns everything. You borrow nodes one at a time via `get_mut`, and if you need to visit neighbors, you collect the `usize` indices first.

