use std::collections::{HashMap, HashSet};

pub struct Graph {
    nodes: Vec<Node>,
}

pub struct Node {
    id: usize,
    value: String,
    // References are just indices into the Graph's nodes vector
    edges: HashSet<usize>,
}

impl Graph {
    pub fn new() -> Self {
        Graph { nodes: Vec::new() }
    }

    pub fn add_node(&mut self, value: String) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            id,
            value,
            edges: HashSet::new(),
        });
        id
    }

    pub fn add_edge(&mut self, from: usize, to: usize) {
        if from < self.nodes.len() && to < self.nodes.len() {
            self.nodes[from].edges.insert(to);
            // For undirected:
            self.nodes[to].edges.insert(from);
        }
    }

    pub fn get_node_mut(&mut self, id: usize) -> Option<&mut Node> {
        self.nodes.get_mut(id)
    }

    pub fn get_node(&self, id: usize) -> Option<&Node> {
        self.nodes.get(id)
    }

    pub fn remove_edge(&mut self, from: usize, to: usize) {
        if let Some(node) = self.nodes.get_mut(from) {
            node.edges.remove(&to);
        }
        if let Some(node) = self.nodes.get_mut(to) {
            node.edges.remove(&from);
        }
    }
}
```
