use std::collections::{HashMap, HashSet};

pub struct IndexGraph {
    nodes: Vec<NodeData>,
}

#[derive(Debug, Clone, Default)]
pub struct NodeData {
    pub value: String,
    pub edges: HashSet<usize>,
}

impl IndexGraph {
    pub fn new() -> Self {
        Self { nodes: Vec::new() }
    }

    pub fn add_node(&mut self, value: impl Into<String>) -> usize {
        let id = self.nodes.len();
        self.nodes.push(NodeData {
            id,
            value: value.into(),
            edges: HashSet::new(),
        });
        id
    }

    pub fn add_edge(&mut self, a: usize, b: usize) {
        if a < self.nodes.len() && b < self.nodes.len() && a != b {
            self.nodes[a].edges.insert(b);
            self.nodes[b].edges.insert(a); // undirected
        }
    }

    /// Mutates the target node's value safely.
    /// Note: We clone edges first so we don't hold a borrow on `self.nodes`
    /// while trying to borrow other nodes.
    pub fn propagate(&mut self, start: usize, delta: i32) {
        // Gather neighbors without holding a mutable borrow
        let neighbors: Vec<usize> = self.nodes.get(start)
            .map(|n| n.edges.iter().cloned().collect())
            .unwrap_or_default();

        // Mutate neighbors individually
        for n in neighbors {
            if let Some(node) = self.nodes.get_mut(n) {
                // Here we parse value as number for demo, but let's just append
                node.value.push_str(&format!(" +{}", delta));
            }
        }

        if let Some(node) = self.nodes.get_mut(start) {
            node.value.push_str(" [origin]");
        }
    }

    pub fn get_value(&self, id: usize) -> Option<&str> {
        self.nodes.get(id).map(|n| n.value.as_str())
    }
}
