use std::fmt;

// ------------------------------------------------------------------
// Arena-based Doubly-Linked List
// References between nodes are usize indices, not Rust borrows.
// This avoids *all* borrow-checker issues with self-referential data.
// ------------------------------------------------------------------

#[derive(Debug, Clone)]
struct ListNode<T> {
    value: T,
    prev: Option<usize>, // index of previous node
    next: Option<usize>, // index of next node
}

pub struct DoublyLinkedList<T> {
    nodes: Vec<ListNode<T>>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            nodes: Vec::new(),
            head: None,
            tail: None,
        }
    }

    /// Push to the tail and return the stable index of the new node.
    pub fn push_back(&mut self, value: T) -> usize {
        let new_idx = self.nodes.len();
        let prev_idx = self.tail;

        self.nodes.push(ListNode {
            value,
            prev: prev_idx,
            next: None,
        });

        // Link the old tail forward
        if let Some(p) = prev_idx {
            self.nodes[p].next = Some(new_idx);
        } else {
            // List was empty
            self.head = Some(new_idx);
        }

        self.tail = Some(new_idx);
        new_idx
    }

    /// Safe mutation: borrow a single value by its stable index.
    /// No other references are invalidated because links are just usize.
    pub fn get_mut(&mut self, idx: usize) -> Option<&mut T> {
        self.nodes.get_mut(idx).map(|n| &mut n.value)
    }

    /// Immutable access.
    pub fn get(&self, idx: usize) -> Option<&T> {
        self.nodes.get(idx).map(|n| &n.value)
    }

    /// Iterate over (index, value) pairs.
    pub fn iter(&self) -> ListIter<'_, T> {
        ListIter {
            list: self,
            current: self.head,
        }
    }
}

pub struct ListIter<'a, T> {
    list: &'a DoublyLinkedList<T>,
    current: Option<usize>,
}

impl<'a, T> Iterator for ListIter<'a, T> {
    type Item = (usize, &'a T);
    fn next(&mut self) -> Option<Self::Item> {
        let idx = self.current?;
        let node = &self.list.nodes[idx];
        self.current = node.next;
        Some((idx, &node.value))
    }
}

impl<T: fmt::Debug> fmt::Debug for DoublyLinkedList<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_list().entries(self.iter().map(|(_, v)| v)).finish()
    }
}

