impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        DoublyLinkedList { nodes: Vec::new(), head: None, tail: None }
    }

    pub fn push_back(&mut self, value: T) -> usize {
        let new_idx = self.nodes.len();
        let prev_idx = self.tail;

        self.nodes.push(ListNode {
            value,
            prev: prev_idx,
            next: None,
        });

        if let Some(prev_idx) = prev_idx {
            self.nodes[prev_idx].next = Some(new_idx);
        } else {
            self.head = Some(new_idx);
        }

        self.tail = Some(new_idx);
        new_idx
    }

    pub fn get_mut(&mut self, idx: usize) -> Option<&mut T> {
        self.nodes.get_mut(idx).map(|node| &mut node.value)
    }

    pub fn get(&self, idx: usize) -> Option<&T> {
        self.nodes.get(idx).map(|node| &node.value)
    }

    pub fn iter(&self) -> Iter<'_, T> {
        Iter { list: self, current: self.head }
    }
}

pub struct Iter<'a, T> {
    list: &'a DoublyLinkedList<T>,
    current: Option<usize>,
}

