use std::cell::RefCell;
use std::rc::Rc;

pub struct Node {
    value: i32,
    prev: Option<Rc<RefCell<Node>>>,
    next: Option<Rc<RefCell<Node>>>,
}

impl Node {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: None,
        }))
    }
}

fn main() {
    let head = Node::new(10);
    let tail = Node::new(20);

    // Link them: head -> tail, and tail <- head
    head.borrow_mut().next = Some(Rc::clone(&tail));
    tail.borrow_mut().prev = Some(Rc::clone(&head));

    // Mutate safely through shared references
    head.borrow_mut().value += 5;
    tail.borrow_mut().value *= 2;

    // Read back
    println!("Head value: {}", head.borrow().value); // 15
    println!("Tail value: {}", tail.borrow().value); // 40

    // Traverse without holding a borrow open across logic
    if let Some(next_rc) = head.borrow().next.clone() {
        println!("Head's next: {}", next_rc.borrow().value);
    }

    // You can also navigate backwards
    if let Some(prev_rc) = tail.borrow().prev.clone() {
