use std::fmt;

#[derive(Debug, Clone, Default)]
pub struct Node {
    pub value: i32,
    pub next: Option<usize>, // stable reference to next node via index
    pub prev: Option<usize>, // stable reference to prev node via index
}

pub struct DoublyLinkedList {
    nodes: Vec<Node>,      // Arena: nodes never move once inserted
    head: Option<usize>,   // Stable ID, not a pointer/reference
    tail: Option<usize>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self {
            nodes: Vec::new(),
            head: None,
            tail: None,
        }
    }

    /// Push a value and return the stable node ID.
    pub fn push_back(&mut self, value: i32) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            value,
            next: None,
            prev: self.tail,
        });

        if let Some(tail_id) = self.tail {
            self.nodes[tail_id].next = Some(id);
        } else {
            self.head = Some(id);
        }
        self.tail = Some(id);
        id
    }

    /// Insert a new value immediately after `after_id`.
    /// Returns the new stable ID, or None if `after_id` is invalid.
    pub fn insert_after(&mut self, after_id: usize, value: i32) -> Option<usize> {
        if after_id >= self.nodes.len() {
            return None;
        }

        // Copy the old link out before we mutate anything.
        let old_next = self.nodes[after_id].next;
        let new_id = self.nodes.len();

        self.nodes.push(Node {
            value,
            next: old_next,
            prev: Some(after_id),
        });

        // Re-link. Each assignment borrows `self.nodes` only for that statement,
        // so the borrow checker never sees overlapping mutable borrows.
        self.nodes[after_id].next = Some(new_id);

        if let Some(next_id) = old_next {
            self.nodes[next_id].prev = Some(new_id);
        }

        if self.tail == Some(after_id) {
            self.tail = Some(new_id);
        }

        Some(new_id)
    }

    /// Mutate a node's value safely using its stable ID.
    pub fn update_value(&mut self, id: usize, value: i32) -> bool {
        if let Some(node) = self.nodes.get_mut(id) {
            node.value = value;
            true
        } else {
            false
        }
    }

    /// Get an immutable view by stable ID.
    pub fn get(&self, id: usize) -> Option<&Node> {
        self.nodes.get(id)
    }

    /// Get a mutable view by stable ID.
    /// Note: the borrow checker prevents using the list elsewhere
    /// while this `&mut Node` is alive, which is exactly what you want.
    pub fn get_mut(&mut self, id: usize) -> Option<&mut Node> {
        self.nodes.get_mut(id)
    }

    pub fn print_forward(&self) {
        let mut curr = self.head;
        while let Some(id) = curr {
            let node = &self.nodes[id];
            print!("{} -> ", node.value);
            curr = node.next;
        }
        println!("null");
    }

    pub fn print_backward(&self) {
        let mut curr = self.tail;
        while let Some(id) = curr {
            let node = &self.nodes[id];
            print!("{} <- ", node.value);
            curr = node.prev;
        }
        println!("null");
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    // Create nodes; IDs are stable for the lifetime of the list.
    let a = list.push_back(10);
    let b = list.push_back(20);
    let c = list.push_back(30);

    println!("Initial:");
    list.print_forward();   // 10 -> 20 -> 30 -> null
    list.print_backward();  // 30 <- 20 <- 10 <- null

    // Insert between a and b.
    let d = list.insert_after(a, 15).expect("invalid id");
    println!("\nAfter inserting 15 after node {}:", a);
    list.print_forward();   // 10 -> 15 -> 20 -> 30 -> null

    // Mutate node c (id={:?}) safely without touching other references.
    list.update_value(c, 99);
    println!("\nAfter mutating node {} to 99:", c);
    list.print_forward();   // 10 -> 15 -> 20 -> 99 -> null
    list.print_backward();

    // Direct mutation via get_mut.
    if let Some(node) = list.get_mut(d) {
        node.value = 42;
    }
    println!("\nAfter mutating inserted node {} to 42:", d);
    list.print_forward();   // 10 -> 42 -> 20 -> 99 -> null
}
