use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct ListNode {
    value: i32,
    // Strong reference: moving forward is cheap
    next: Option<Rc<RefCell<ListNode>>>,
    // Weak reference: prevents a reference cycle (head <-> tail leaks)
    prev: Option<Weak<RefCell<ListNode>>>,
}

impl ListNode {
    fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(ListNode {
            value,
            next: None,
            prev: None,
        }))
    }
}

fn main() {
    // 1. Create nodes (no borrow checker issues here)
    let head = ListNode::new(10);
    let tail = ListNode::new(30);

    // 2. Link head -> tail
    head.borrow_mut().next = Some(tail.clone());
    tail.borrow_mut().prev = Some(Rc::downgrade(&head));

    // 3. Insert a middle node and rewire links
    let middle = ListNode::new(20);

    // We borrow each Rc/RefCell in isolated, short scopes so we never
    // hold two mutable borrows on the same node at once.
    head.borrow_mut().next = Some(middle.clone());      // head -> middle
    middle.borrow_mut().prev = Some(Rc::downgrade(&head)); // middle <- head

    middle.borrow_mut().next = Some(tail.clone());      // middle -> tail
    tail.borrow_mut().prev = Some(Rc::downgrade(&middle)); // middle <- tail

    // 4. Mutate through a back-reference (tail -> middle -> head)
    if let Some(weak_prev) = tail.borrow().prev.clone() {
        if let Some(strong_prev) = weak_prev.upgrade() {
            strong_prev.borrow_mut().value = 99; // mutate middle's value via back-link
        }
    }

    // 5. Read values safely
    println!(
        "head={}, middle={}, tail={}",
        head.borrow().value,
        middle.borrow().value,
        tail.borrow().value
    );
}
```

