```rust
use std::cell::RefCell;
use std::rc::Rc;

pub struct GraphNode {
    id: u32,
    label: String,
    edges: Vec<Rc<RefCell<GraphNode>>>,
}

impl GraphNode {
    /// Create a new node wrapped in an Rc so it can be shared/referenced.
    pub fn new(id: u32, label: impl Into<String>) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(GraphNode {
            id,
            label: label.into(),
            edges: Vec::new(),
        }))
    }

    /// Connect two nodes bidirectionally.
    /// Note: We clone the Rc handles *before* borrowing to avoid overlapping borrows.
    pub fn connect(a: &Rc<RefCell<GraphNode>>, b: &Rc<RefCell<GraphNode>>) {
        if Rc::ptr_eq(a, b) {
            return; // Prevent self-loop and duplicate borrow panic
        }

        let b_rc = b.clone();
        a.borrow_mut().edges.push(b_rc);

        let a_rc = a.clone();
        b.borrow_mut().edges.push(a_rc);
    }

    /// Break the connection between two nodes.
    pub fn disconnect(a: &Rc<RefCell<GraphNode>>, b: &Rc<RefCell<GraphNode>>) {
        if Rc::ptr_eq(a, b) {
            return;
        }

        // Read IDs first in separate scopes so borrows don't overlap.
        let b_id = b.borrow().id;
        a.borrow_mut().edges.retain(|edge| edge.borrow().id != b_id);

        let a_id = a.borrow().id;
        b.borrow_mut().edges.retain(|edge| edge.borrow().id != a_id);
    }

    /// Safely mutate a node's label through shared references.
    pub fn set_label(node: &Rc<RefCell<GraphNode>>, label: impl Into<String>) {
        node.borrow_mut().label = label.into();
    }

    /// Read neighbor IDs without holding long-lived borrows.
    pub fn neighbors(node: &Rc<RefCell<GraphNode>>) -> Vec<u32> {
        node.borrow()
            .edges
            .iter()
            .map(|edge| edge.borrow().id)
            .collect()
    }

    pub fn print(node: &Rc<RefCell<GraphNode>>) {
        let n = node.borrow();
        let neighbor_ids: Vec<u32> = n.edges.iter().map(|e| e.borrow().id).collect();
        println!("Node {} ({}) -> neighbors: {:?}", n.id, n.label, neighbor_ids);
    }
}

fn main() {
    let n1 = GraphNode::new(1, "Alpha");
    let n2 = GraphNode::new(2, "Beta");
    let n3 = GraphNode::new(3, "Gamma");

    // Build the graph
    GraphNode::connect(&n1, &n2);
    GraphNode::connect(&n2, &n3);
    GraphNode::connect(&n1, &n3);

    GraphNode::print(&n1);
    GraphNode::print(&n2);

    // Mutate safely through the Rc reference
    GraphNode::set_label(&n2, "Updated Beta");
    println!("N1's neighbors after mutation: {:?}", GraphNode::neighbors(&n1));

    // Disconnect and print again
    GraphNode::disconnect(&n1, &n3);
    GraphNode::print(&n1);
}
```

### Why this avoids your lifetimes problem

- **No `'a` annotations**: Because nodes own each other via `Rc` (reference counting) rather than borrowed references (`&`), Rust's compile-time borrow checker doesn't need to track lifetimes across the graph.
- **Runtime borrow checks**: `RefCell` allows you to call `.borrow()` (immutable) or `.borrow_mut()` (mutable). As long as you don't try to `borrow_mut()` the *same* node twice at once, it works. The code above separates borrows (e.g., reading `b.id` before calling `borrow_mut()` on `a`) to prevent runtime panics.
- **No `unsafe`**: All references are memory-safe.

