```rust
use std::cell::RefCell;
use std::rc::Rc;

type Link<T> = Option<Rc<RefCell<Node<T>>>>;

pub struct Node<T> {
    pub value: T,
    pub next: Link<T>,
    pub prev: Link<T>,
}

impl<T> Node<T> {
    pub fn new(value: T) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

pub struct DoublyLinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self { head: None, tail: None }
    }

    pub fn push_back(&mut self, value: T) {
        let node = Node::new(value);
        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(node.clone());
                // Link new node <- old tail
                node.borrow_mut().prev = Some(old_tail);
                self.tail = Some(node);
            }
            None => {
                // Empty list
                self.head = Some(node.clone());
                self.tail = Some(node);
            }
        }
    }

    pub fn push_front(&mut self, value: T) {
        let node = Node::new(value);
        match self.head.take() {
            Some(old_head) => {
                old_head.borrow_mut().prev = Some(node.clone());
                node.borrow_mut().next = Some(old_head);
                self.head = Some(node);
            }
            None => {
                self.tail = Some(node.clone());
                self.head = Some(node);
            }
        }
    }

    /// Returns a clone of the head `Rc` so you can borrow-mut it later.
    pub fn head_node(&self) -> Option<Rc<RefCell<Node<T>>>> {
        self.head.clone()
    }

    /// Traverse and apply a mutation. The closure receives `&Rc<RefCell<Node<T>>>`
    /// so it can call `.borrow_mut()` inside.
    pub fn traverse_mut<F>(&self, mut f: F)
    where
        F: FnMut(&Rc<RefCell<Node<T>>>),
    {
        let mut current = self.head.clone();
        while let Some(node) = current {
            // Apply user mutation (e.g., change value or links)
            f(&node);

            // Move to next; the temporary borrow from `borrow()` is
            // dropped immediately after the clone.
            current = node.borrow().next.clone();
        }
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    // Safe mutation: borrow the head, change its value
    if let Some(n) = list.head_node() {
        n.borrow_mut().value = 99;
    }

    // Safe mutation of every node's label/value during traversal
    list.traverse_mut(|node| {
        let mut bor = node.borrow_mut();
        bor.value += 1;
        // You could also rewiring links here at runtime:
        // bor.next = ...
    });

    // Verify results
    list.traverse_mut(|node| {
        println!("{}", node.borrow().value);
    });
}
```

### Why this works (no lifetime annotations needed)

| Pattern | What it solves |
|---|---|
| `Rc<T>` | Nodes can point to each other with cloned references (` Some(node.clone()) `) without borrowing. There is no `&Node` that needs a lifetime. |
| `RefCell<T>` | Gives you `borrow_mut()` at **runtime**. The compiler allows multiple `Rc` clones; `RefCell` panics at runtime only if you illegally double-borrow mutably, replacing the compile-time borrow checker for these shared nodes. |
| No `&`/`&mut` stored in structs | Every field (`next`, `prev`, `edges`) holds an owned `Option<Rc<...>>`, not a reference. Therefore `struct Node` needs no `<'a>` parameter. |

