use std::cell::RefCell;
use std::rc::Rc;

// ------------------------------------------------------------------
// No lifetime annotations (`<'a>`) appear anywhere in this file.
// ------------------------------------------------------------------

#[derive(Debug, Default)]
pub struct Node {
    id: String,
    // Nodes point to each other via shared, mutable references
    neighbors: Vec<Rc<RefCell<Node>>>,
}

pub struct Graph {
    nodes: Vec<Rc<RefCell<Node>>>,
}

impl Graph {
    pub fn new() -> Self {
        Graph { nodes: Vec::new() }
    }

    pub fn add_node(&mut self, id: impl Into<String>) -> Rc<RefCell<Node>> {
        let node = Rc::new(RefCell::new(Node {
            id: id.into(),
            neighbors: Vec::new(),
        }));
        self.nodes.push(node.clone());
        node
    }

    /// Creates a mutual reference between two nodes.
    pub fn connect(&self, a: &Rc<RefCell<Node>>, b: &Rc<RefCell<Node>>) {
        // borrow_mut() is safe here because we drop it immediately
        // after the push. Use blocks `{}` to keep scopes tight.
        {
            let mut a_ref = a.borrow_mut();
            a_ref.neighbors.push(b.clone());
        }
        {
            let mut b_ref = b.borrow_mut();
            b_ref.neighbors.push(a.clone());
        }
    }

    pub fn display(&self) {
        for node_rc in &self.nodes {
            // Immutable borrow to read data
            let node = node_rc.borrow();

            // Even though there's a reference cycle (A -> B -> A),
            // immutable borrows don't conflict.
            let neighbor_ids: Vec<String> = node
                .neighbors
                .iter()
                .map(|n| n.borrow().id.clone())
                .collect();

            println!("Node {} -> {:?}", node.id, neighbor_ids);
        }
    }
}

fn main() {
    let mut graph = Graph::new();

    let alice = graph.add_node("Alice");
    let bob = graph.add_node("Bob");
    let charlie = graph.add_node("Charlie");

    // Mutual references (cycle)
    graph.connect(&alice, &bob);
    graph.connect(&alice, &charlie);

    // Mutate through a shared reference—no borrow-checker fight.
    {
        let mut a = alice.borrow_mut();
        a.id = "Alicia".to_string();
        // You can also re-wire neighbors here safely
        a.neighbors.clear();
    }

    graph.display();
}
```

