```rust
use std::fmt;

#[derive(Debug, Default)]
struct Node {
    value: i32,
    prev: Option<usize>,
    next: Option<usize>,
}

#[derive(Debug, Default)]
struct DoublyLinkedList {
    nodes: Vec<Node>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl DoublyLinkedList {
    fn new() -> Self {
        Self::default()
    }

    fn push_back(&mut self, value: i32) -> usize {
        let id = self.nodes.len();
        let prev_link = self.tail;

        // Push the new node. This borrows `self.nodes` briefly.
        self.nodes.push(Node {
            value,
            prev: prev_link,
            next: None,
        });

        // Link the old tail to this new node.
        if let Some(tail_id) = prev_link {
            self.nodes[tail_id].next = Some(id);
        }

        // Update list head/tail.
        self.tail = Some(id);
        if self.head.is_none() {
            self.head = Some(id);
        }

        id
    }

    fn remove(&mut self, id: usize) {
        if id >= self.nodes.len() {
            return;
        }

        // CRITICAL: extract links in an inner scope so we don't hold
        // a borrow on `self.nodes[id]` while we mutate neighbors.
        let (prev, next) = {
            let node = &self.nodes[id];
            (node.prev, node.next)
        };

        // Unlink previous node.
        if let Some(p) = prev {
            self.nodes[p].next = next;
        } else {
            self.head = next; // We removed the head.
        }

        // Unlink next node.
        if let Some(n) = next {
            self.nodes[n].prev = prev;
        } else {
            self.tail = prev; // We removed the tail.
        }

        // Optional: clear the removed node's links.
        self.nodes[id].prev = None;
        self.nodes[id].next = None;
    }

    fn traverse_forward(&self) {
        let mut current = self.head;
        while let Some(id) = current {
