use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. We clone the old head Rc, borrow it briefly to
    /// wire `prev`, then immediately drop that borrow before updating `self.head`.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        if let Some(old_head) = self.head.as_ref() {
            // Borrow is confined to this block
            old_head.borrow_mut().prev = Some(new_node.clone());
        } else {
            // List was empty; new node is also the tail
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    /// Push to the back. Symmetric to push_front.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.as_ref() {
            old_tail.borrow_mut().next = Some(new_node.clone());
        } else {
            // List was empty
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    /// Pop from the front.
    /// 1. Take the head Rc out of the list.
    /// 2. Disconnect and capture the next node.
    /// 3. Update list pointers.
    /// 4. Use `Rc::try_unwrap` to take ownership of the isolated node and extract `T`.
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;

        // Disconnect head and grab the next pointer
        let next_rc = {
            let mut head = head_rc.borrow_mut();
            head.prev = None;
            head.next.take()
        };

        if let Some(next) = next_rc.as_ref() {
            next.borrow_mut().prev = None;
            self.head = Some(next.clone());
        } else {
            self.head = None;
            self.tail = None;
        }

        // At this point head_rc should have exactly 1 strong reference
        let node_refcell = Rc::try_unwrap(head_rc).ok()?;
        Some(node_refcell.into_inner().value)
    }

    /// Pop from the back.
    /// Same disconnect-then-unwrap strategy as pop_front.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;

        // Disconnect tail and grab the prev pointer
        let prev_rc = {
            let mut tail = tail_rc.borrow_mut();
            tail.next = None;
            tail.prev.take()
        };

        if let Some(prev) = prev_rc.as_ref() {
            prev.borrow_mut().next = None;
            self.tail = Some(prev.clone());
        } else {
            self.head = None;
            self.tail = None;
        }

        let node_refcell = Rc::try_unwrap(tail_rc).ok()?;
        Some(node_refcell.into_inner().value)
    }

    /// Clear the list by repeatedly popping from the front.
    /// This also breaks any internal reference cycles before `Drop` runs.
    pub fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        // Manually drain so we don't leak in the presence of accidental cycles.
        self.clear();
    }
}

