    list.push_front(10);
    list.push_back(20);
    list.push_front(5);

    println!("Length: {}", list.len()); // 3

    assert_eq!(list.pop_front(), Some(5));
    assert_eq!(list.pop_back(), Some(20));
    assert_eq!(list.pop_back(), Some(10));
    assert_eq!(list.pop_back(), None);

    println!("All operations completed successfully.");
}
