    nodes: Vec<Rc<RefCell<Node>>>,
}

impl Graph {
    pub fn new() -> Self {
        Self { nodes: Vec::new() }
    }

    /// Create a node and return a shared reference to it.
    pub fn add_node(&mut self, value: impl Into<String>) -> Rc<RefCell<Node>> {
        let node = Rc::new(RefCell::new(Node::new(self.nodes.len(), value)));
        self.nodes.push(node.clone());
