use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node that knows about its neighbors via owned/shared references.
struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>, // Weak avoids a strong reference cycle
}

/// The list only holds the two ends; nodes hold each other.
pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
        }
    }

    /// Push to the back while maintaining prev/next links.
    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
                // Link new node -> old tail (weak so cycles don't leak memory)
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));

                self.tail = Some(new_node);
            }
            None => {
                // Empty list: head and tail are the same node
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_node);
            }
        }
    }

    /// Remove from the front and repair the links.
    pub fn pop_front(&mut self) -> Option<i32> {
        self.head.take().map(|old_head| {
            // Copy out the value (i32 is Copy, so the borrow ends immediately)
            let val = old_head.borrow().value;

