                    new_head.borrow_mut().prev = None;
                    self.head = Some(new_head);
                }
                None => {
                    // We removed the only node
                    self.tail = None;
                }
            }
            val
        })
    }

    /// Safe mutation of a node in the middle (if you hold its Rc elsewhere).
    pub fn update_value(node: &Rc<RefCell<Node>>, new_value: i32) {
        node.borrow_mut().value = new_value;
    }
}

fn main() {
