use std::cell::RefCell;
use std::rc::{Rc, Weak};

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Weak<RefCell<Node>>>,
}

struct Node {
    value: i32,
    prev: Option<Weak<RefCell<Node>>>,
    next: Option<Rc<RefCell<Node>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
        }
    }

    /// Push to the front.
    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(), // link to old head
        }));

        if let Some(old_head) = self.head.take() {
            old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
        } else {
            // List was empty: this is also the tail.
            self.tail = Some(Rc::downgrade(&new_node));
        }

        self.head = Some(new_node);
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(tail_weak) = self.tail.take() {
            if let Some(tail_rc) = tail_weak.upgrade() {
                tail_rc.borrow_mut().next = Some(new_node.clone());
            }
        } else {
            // List was empty.
            self.head = Some(new_node.clone());
        }

        self.tail = Some(Rc::downgrade(&new_node));
    }

    /// Remove and return the front value.
    pub fn pop_front(&mut self) -> Option<i32> {
        self.head.take().map(|old_head| {
            let value = old_head.borrow().value;
            let next = old_head.borrow().next.clone();

            if let Some(next_rc) = next {
                // Update the new head's back-link.
                next_rc.borrow_mut().prev = None;
                self.head = Some(next_rc);
            } else {
                // List is now empty.
                self.head = None;
                self.tail = None;
            }

            value
        })
    }

    /// Print state for debugging.
    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            let val = node_rc.borrow().value;
            print!("{} ", val);
            current = node_rc.borrow().next.clone();
        }
        println!();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(10);
    list.push_front(5);
    list.push_back(20);
    list.print_forward(); // 5 10 20
    assert_eq!(list.pop_front(), Some(5));
    list.print_forward(); // 10 20
}
```

### Why this works (and why lifetimes failed you)

* **No lifetime annotations**: The nodes don't hold references (`&Node`) with lifetimes. They hold `Rc` (shared ownership pointer) and `Weak` (non-owning pointer). The borrow checker doesn't need to track relationships across nodes because ownership is dynamic, not static.
* **Runtime borrow checking**: `RefCell` allows mutation through a shared `Rc`. The `.borrow()` and `.borrow_mut()` calls check at **runtime** that you don't have conflicting mutable borrows. If you accidentally borrow the same node mutably twice in the same call stack, it panics—this is the trade-off for escaping the compile-time borrow checker.
* **No cycles / leaks**: The backward `prev` links are `Weak`, so when you drop the list (or pop nodes), the reference counts can reach zero properly.

