```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node in a doubly-linked list.
/// - `Rc` allows multiple parts of the list to own it.
/// - `RefCell` lets us mutate it through shared references.
/// - `prev` is `Weak` so that back-links don't create reference cycles.
struct ListNode {
    value: i32,
    next: Option<Rc<RefCell<ListNode>>>,
    prev: Option<Weak<RefCell<ListNode>>>,
}

impl ListNode {
    fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(ListNode {
            value,
            next: None,
            prev: None,
        }))
    }
}

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<ListNode>>>,
    tail: Option<Rc<RefCell<ListNode>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        DoublyLinkedList {
            head: None,
            tail: None,
        }
    }

    /// Append a value. This demonstrates safe mutation through `Rc<RefCell<...>>`.
    pub fn push_back(&mut self, value: i32) {
        let new_node = ListNode::new(value);

        match self.tail.take() {
            Some(old_tail) => {
                // Mutate the old tail to point forward.
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
                // Mutate the new node to point backward (weak, to avoid cycles).
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                self.tail = Some(new_node);
            }
            None => {
                // List was empty.
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_node);
            }
        }
    }

    /// Remove and return the back value.
    pub fn pop_back(&mut self) -> Option<i32> {
        let tail_rc = self.tail.take()?;

        // Extract data before we start rewiring neighbors.
        let (value, prev_weak) = {
            let node_ref = tail_rc.borrow();
            (node_ref.value, node_ref.prev.clone())
        }; // Borrow ends here.

        // Rewire the previous node (if any) to become the new tail.
        if let Some(prev_rc) = prev_weak.and_then(|w| w.upgrade()) {
            prev_rc.borrow_mut().next = None;
            self.tail = Some(prev_rc);
        } else {
            // We just removed the only node.
            self.head = None;
        }

        Some(value)
    }

    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        print!("Forward: ");
        while let Some(node_rc) = current {
            print!("{} ", node_rc.borrow().value);
            current = node_rc.borrow().next.clone();
        }
        println!();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_back(10);
    list.push_back(20);
    list.push_back(30);
    list.print_forward(); // Forward: 10 20 30

    if let Some(v) = list.pop_back() {
        println!("Popped: {}", v); // Popped: 30
    }

    list.print_forward(); // Forward: 10 20
}
```

