```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

type Forward = Option<Rc<RefCell<Node>>>;
type Backward = Option<Weak<RefCell<Node>>>;

pub struct Node {
    value: i32,
    next: Forward,
    prev: Backward,
}

impl Node {
    /// Create a new node wrapped in Rc<RefCell<...>>
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }

    /// Insert `value` immediately after `node`.
    /// No lifetimes are needed because Rc handles ownership.
    pub fn insert_after(node: &Rc<RefCell<Self>>, value: i32) {
        let new_node = Node::new(value);

        // 1. Read the current forward pointer without holding a borrow
        let old_next: Forward = {
            let current = node.borrow();
            current.next.clone()
        };

        // 2. Set up the new node's links
        new_node.borrow_mut().prev = Some(Rc::downgrade(node));
        new_node.borrow_mut().next = old_next.clone();

        // 3. Patch the old next node's back-pointer to point back to new_node
        if let Some(ref next_rc) = old_next {
            next_rc.borrow_mut().prev = Some(Rc::downgrade(&new_node));
        }

        // 4. Point current node forward to the new node
        node.borrow_mut().next = Some(new_node);
    }

    /// Safe mutation: no lifetime annotations required.
    pub fn set_value(node: &Rc<RefCell<Self>>, value: i32) {
        node.borrow_mut().value = value;
    }

    /// Safe read.
    pub fn value(node: &Rc<RefCell<Self>>) -> i32 {
        node.borrow().value
    }
}

fn main() {
    // Build: 1 <-> 3
    let head = Node::new(1);
    let tail = Node::new(3);

    head.borrow_mut().next = Some(tail.clone());
    tail.borrow_mut().prev = Some(Rc::downgrade(&head));

    // Insert 2 in the middle -> 1 <-> 2 <-> 3
    Node::insert_after(&head, 2);

    // Mutate safely via shared reference
    Node::set_value(&head, 100);

    // Traverse forward
    let mut current: Option<Rc<RefCell<Node>>> = Some(head.clone());
    while let Some(node_rc) = current {
        println!("Value: {}", Node::value(&node_rc));
        // Clone the Rc inside the Option to move forward
        current = node_rc.borrow().next.clone();
    }
}
```

### Why this works without lifetime errors
| Component | Purpose |
|---|---|
| `Rc<RefCell<Node>>` | Multiple nodes can "own" a reference to the same node. `RefCell` lets you mutate (`borrow_mut`) or read (`borrow`) at **runtime** instead of compile-time. |
| `Weak<RefCell<Node>>` | Used for `prev`. If both directions were `Rc`, nodes would keep each other alive forever (memory leak / cycle). `Weak` doesn't increment the strong count. |
| No `&` references in storage | Because the nodes live inside `Rc`, the compiler doesn't need to prove that borrowed pointers outlive each other. The borrow checker is satisfied immediately. |

### If you want a small graph instead
The exact same pattern applies. Replace `next`/`prev` with a `Vec<Rc<RefCell<Node>>>` for adjacency lists:

```rust
pub struct GraphNode {
    id: usize,
    neighbors: Vec<Rc<RefCell<GraphNode>>>,
}
```

Then `link(a, b)` just pushes clones into both `neighbors` vectors.

### One runtime warning
Because `RefCell` checks borrows at **runtime**, you can still panic if you try to `borrow_mut()` the same node twice in overlapping scopes. The code above avoids that by scoping borrows tightly (using blocks like `{ let current = node.borrow(); ... }`).

