            }
            None => {
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
    }

    /// Pop from the front.
    pub fn pop_front(&mut self) -> Option<i32> {
        self.head.take().map(|old_head| {
            // Read value and next pointer separately to avoid holding a borrow.
            let value = old_head.borrow().value;
            let next_opt = old_head.borrow().next.clone();

            if let Some(next) = next_opt {
                next.borrow_mut().prev = None;
                self.head = Some(next);
            } else {
                self.head = None;
                self.tail = None;
            }
            value
        })
    }

    /// Pop from the back.
    pub fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|old_tail| {
            let value = old_tail.borrow().value;
            let prev_weak = old_tail.borrow().prev.clone();

