use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node that can be mutated even when shared.
#[derive(Debug)]
struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

impl Node {
    fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

/// The list tracks only head and tail; nodes link themselves.
#[derive(Debug, Default)]
struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
    len: usize,
}

impl DoublyLinkedList {
    fn new() -> Self {
        Self::default()
    }

    /// Append to the back.
    fn push_back(&mut self, value: i32) {
        let new_node = Node::new(value);

        match self.tail.take() {
            Some(old_tail) => {
                // old_tail -> new_node (strong)
                old_tail.borrow_mut().next = Some(new_node.clone());
                // new_node <- old_tail (weak, avoids cycle)
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                self.tail = Some(new_node);
            }
            None => {
                // Empty list: head and tail are the same node.
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Remove from the back and return the value.
    fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|old_tail| {
            // Upgrade the weak prev link inside an explicit scope
            // so the borrow is released before we try to consume `old_tail`.
            let prev_rc = {
                let borrowed = old_tail.borrow();
                borrowed.prev.clone().and_then(|w| w.upgrade())
            };

            if let Some(prev) = prev_rc {
                prev.borrow_mut().next = None;
                self.tail = Some(prev);
            } else {
                self.head = None;
            }

            self.len -= 1;

            // Only succeeds if no other strong refs remain (e.g., head/prev already cleared).
            Rc::try_unwrap(old_tail).ok().map(|cell| cell.into_inner().value)
        })
    }

    fn len(&self) -> usize {
        self.len
    }

    fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Iterate without lifetime annotations.
    fn iter(&self) -> Iter {
        Iter {
            current: self.head.clone(),
        }
    }
}

/// Simple forward iterator.
struct Iter {
    current: Option<Rc<RefCell<Node>>>,
}

impl Iterator for Iter {
    type Item = i32;
    fn next(&mut self) -> Option<Self::Item> {
        let current = self.current.take()?;
        let (value, next) = {
            let borrowed = current.borrow();
            (borrowed.value, borrowed.next.clone())
        };
        self.current = next;
        Some(value)
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(1);
    list.push_back(2);
    list.push_back(3);

    println!("Forward: {:?}", list.iter().collect::<Vec<_>>());

    println!("Popped: {:?}", list.pop_back());
    println!("Popped: {:?}", list.pop_back());

    println!("Remaining: {:?}", list.iter().collect::<Vec<_>>());
}
