use std::rc::{Rc, Weak};

/// A node in the doubly-linked list.
#[derive(Debug)]
struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

impl Node {
    fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }
}

/// The list itself. We only need to track head and tail.
#[derive(Debug, Default)]
struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
    len: usize,
}

impl DoublyLinkedList {
    fn new() -> Self {
        Self::default()
    }

    /// Add a node to the back.
    fn push_back(&mut self, value: i32) {
        let new_node = Node::new(value);

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(new_node.clone());
                // Link new node <- old tail (weak to avoid cycles)
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));
                self.tail = Some(new_node);
            }
            None => {
                // List was empty
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Remove and return the back node's value.
    fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|old_tail| {
            // Extract the weak prev pointer and upgrade it, then drop the borrow.
            let prev_rc = {
                let borrowed = old_tail.borrow();
                borrowed.prev.clone().and_then(|w| w.upgrade())
            };

            if let Some(prev) = prev_rc {
                prev.borrow_mut().next = None;
                self.tail = Some(prev);
            } else {
                self.head = None;
            }

            self.len -= 1;

            // Consume the Rc if no other strong refs exist.
            Rc::try_unwrap(old_tail).ok().map(|cell| cell.into_inner().value)
        })
    }

    /// Forward iterator over values.
    fn iter(&self) -> Iter {
        Iter {
            current: self.head.clone(),
        }
    }

    fn len(&self) -> usize {
        self.len
    }

    fn is_empty(&self) -> bool {
        self.len == 0
    }
}

