use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node in the doubly-linked list.
struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

/// The list wrapper.
pub struct DList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl DList {
    pub fn new() -> Self {
        DList {
            head: None,
            tail: None,
        }
    }

    /// Add a node to the back.
    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: self.tail.as_ref().map(|t| Rc::downgrade(t)),
        }));

        if let Some(tail) = self.tail.take() {
            tail.borrow_mut().next = Some(Rc::clone(&new_node));
        } else {
            self.head = Some(Rc::clone(&new_node));
        }
        self.tail = Some(new_node);
    }

    /// Add a node to the front.
    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: self.head.take(),
            prev: None,
        }));

        if let Some(ref head) = new_node.borrow().next {
            head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
        } else {
            // List was empty, so new node is also the tail.
            self.tail = Some(Rc::clone(&new_node));
        }

        self.head = Some(new_node);
    }

    /// Remove and return the front value.
    pub fn pop_front(&mut self) -> Option<i32> {
        self.head.take().map(|old_head| {
            let next = old_head.borrow_mut().next.take();
            if let Some(ref next_node) = next {
                next_node.borrow_mut().prev = None;
            }
            self.head = next.clone();
            if self.head.is_none() {
                self.tail = None;
            }
            old_head.borrow().value
        })
    }

    /// Find a node by value and return an Rc reference for mutation.
    pub fn find_mut_ref(&self, value: i32) -> Option<Rc<RefCell<Node>>> {
        let mut current = self.head.clone();
        while let Some(node) = current {
            if node.borrow().value == value {
                return Some(node);
            }
            current = node.borrow().next.clone();
        }
        None
    }

    /// Iterate over values.
    pub fn iter(&self) -> Iter {
        Iter {
            current: self.head.clone(),
        }
    }
}

/// Simple iterator that clones Rcs.
pub struct Iter {
    current: Option<Rc<RefCell<Node>>>,
}

impl Iterator for Iter {
    type Item = i32;
    fn next(&mut self) -> Option<Self::Item> {
        self.current.take().map(|node| {
            let next = node.borrow().next.clone();
            self.current = next;
            node.borrow().value
        })
    }
}

fn main() {
    let mut list = DList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_front(5);

    // Demonstrate mutation through a shared reference.
    if let Some(node) = list.find_mut_ref(20) {
        node.borrow_mut().value = 99;
    }

    println!("Values:");
    for v in list.iter() {
        println!("{}", v); // Should print 5, 10, 99
    }

    assert_eq!(list.pop_front(), Some(5));
    assert_eq!(list.pop_front(), Some(10));
    assert_eq!(list.pop_front(), Some(99));
    assert_eq!(list.pop_front(), None);
}
```

