```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// A node in a doubly-linked list. 
/// `next` is strong (`Rc`) so we can move forward easily.
/// `prev` is weak (`Weak`) so we don't create a memory-leaking cycle.
pub struct ListNode {
    pub value: i32,
    pub next: Option<Rc<RefCell<ListNode>>>,
    pub prev: Option<Weak<RefCell<ListNode>>>,
}

impl ListNode {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(ListNode {
            value,
            next: None,
            prev: None,
        }))
    }
}

/// The list structure holds only the head and tail.
pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<ListNode>>>,
    tail: Option<Rc<RefCell<ListNode>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self { head: None, tail: None }
    }

    /// Append to the end.
    pub fn push_back(&mut self, value: i32) {
        let new_node = ListNode::new(value);
        let new_ref = Rc::clone(&new_node);

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail -> new node
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
                new_node.borrow_mut().prev = Some(Rc::downgrade(&old_tail));

                self.tail = Some(new_ref);
            }
            None => {
                // First element
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_ref);
            }
        }
    }

    /// Prepend to the front.
    pub fn push_front(&mut self, value: i32) {
        let new_node = ListNode::new(value);
        let new_ref = Rc::clone(&new_node);

        match self.head.take() {
            Some(old_head) => {
                new_node.borrow_mut().next = Some(Rc::clone(&old_head));
                old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));

                self.head = Some(new_ref);
            }
            None => {
                self.head = Some(new_ref);
                self.tail = Some(new_ref);
            }
        }
    }

    /// Remove and return the last value.
    pub fn pop_back(&mut self) -> Option<i32> {
        let tail_rc = self.tail.take()?;

        // Read value and detach prev link in one borrow scope
        let (value, prev_weak) = {
            let mut borrowed = tail_rc.borrow_mut();
            (borrowed.value, borrowed.prev.take())
        };

        if let Some(prev_weak) = prev_weak {
            if let Some(prev_rc) = prev_weak.upgrade() {
                prev_rc.borrow_mut().next = None;
                self.tail = Some(prev_rc);
            }
        } else {
            // It was the only element
            self.head = None;
        }

        Some(value)
    }

    /// Traverse and apply a mutation to every node.
    /// Note the pattern: clone the `next` pointer before mutating.
    pub fn mutate_all<F>(&mut self, mut apply: F)
    where
        F: FnMut(i32) -> i32,
    {
        let mut current = self.head.clone();
        while let Some(node) = current {
            // Mutate the current node
            let new_val = {
                let old = node.borrow().value;
                apply(old)
            };
            node.borrow_mut().value = new_val;

            // Clone the pointer to the next node BEFORE borrowing again
            current = node.borrow().next.clone();
        }
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    // Build the list
    list.push_back(10);
    list.push_back(20);
    list.push_front(5); // List is now: 5 <-> 10 <-> 20

    // Safely mutate every node (no borrow conflicts)
    list.mutate_all(|v| v + 100);

    // Print by popping back
    println!("Popped values:");
    while let Some(v) = list.pop_back() {
        println!("{}", v); // 120, 110, 105
    }
}
```

### Why this works (and avoids your lifetime nightmare)

| Pattern | Why it’s used here |
|---|---|
| `Rc<RefCell<T>>` | `Rc` gives shared ownership (multiple nodes can point to each other). `RefCell` allows mutation (`borrow_mut()`) without needing a mutable reference to the outer container. |
| `Weak` for `prev` | If both directions were `Rc`, nodes would keep each other alive forever (a reference cycle). `Weak` breaks the cycle but still allows backward traversal when needed (`upgrade()`). |
| No `&` references in nodes | Because there are no borrow-checker lifetimes (`'a`) on struct fields. The compiler is happy because ownership is explicit. |
| Clone pointer before borrow | During traversal we clone `next` (`Option<Rc<...>>`) before calling `borrow_mut()`. This prevents holding a borrow across the loop step. |

### Extending to a small graph
If you need an arbitrary graph instead of a list, the pattern is identical: each node holds `Vec<Rc<RefCell<Node>>>` for neighbors. Use `Weak` for edges that shouldn’t own the target (e.g., “parent” or “source” links), and `Rc` for edges that should. The borrow rules remain the same: never hold a `RefCell` borrow while you clone or restructure other pointers.

### One runtime caveat
Because `RefCell` enforces borrow rules at **runtime**, a logic error (like borrowing mutably twice in nested calls) will panic at runtime rather than being caught at compile time. The code above avoids that by keeping borrows in tight, non-overlapping scopes.

