use std::cell::RefCell;
use std::rc::{Rc, Weak};

// ------------------------------------------------------------------
// Node
// ------------------------------------------------------------------
pub struct ListNode {
    value: i32,
    // Strong reference to the next node (list flows forward with Rc)
    next: Option<Rc<RefCell<ListNode>>>,
    // Weak reference back to previous node (prevents reference cycles)
    prev: Option<Weak<RefCell<ListNode>>>,
}

impl ListNode {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(ListNode {
            value,
            next: None,
            prev: None,
        }))
    }
}

// ------------------------------------------------------------------
// Doubly-Linked List
// ------------------------------------------------------------------
pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<ListNode>>>,
    tail: Option<Weak<RefCell<ListNode>>>, // Weak so tail doesn't lock head in a cycle
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        DoublyLinkedList { head: None, tail: None }
    }

    /// Append to the tail. No lifetimes needed—Rc handles ownership.
    pub fn push_back(&mut self, value: i32) {
        let new_node = ListNode::new(value);

        match self.tail.take() {
            Some(tail_weak) => {
                // Try to reach the old tail through its weak pointer
                if let Some(tail_rc) = tail_weak.upgrade() {
                    // Link old tail -> new node
                    tail_rc.borrow_mut().next = Some(Rc::clone(&new_node));
                    // Link new node <- old tail
                    new_node.borrow_mut().prev = Some(Rc::downgrade(&tail_rc));
                    self.tail = Some(Rc::downgrade(&new_node));
                } else {
                    // Defensive: previous tail was dropped (shouldn't happen in healthy list)
                    self.head = Some(Rc::clone(&new_node));
                    self.tail = Some(Rc::downgrade(&new_node));
                }
            }
            None => {
                // List was empty
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(Rc::downgrade(&new_node));
            }
        }
    }

    /// Immutable traversal—demonstrates shared borrow via Rc::clone.
    pub fn print_forward(&self) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            let node = node_rc.borrow();          // immutable borrow
            print!("{} ", node.value);
            current = node.next.clone();            // clone Rc, then drop borrow
        }
        println!();
    }

    /// Mutate every node in place—demonstrates interior mutability.
    /// Notice we clone the `next` Rc BEFORE calling borrow_mut(),
    /// so we never hold two borrows on the same RefCell.
    pub fn increment_all(&self, amount: i32) {
        let mut current = self.head.clone();
        while let Some(node_rc) = current {
            let next = node_rc.borrow().next.clone(); // read & clone next
            node_rc.borrow_mut().value += amount;      // mutate value
            current = next;
        }
    }

    /// Direct mutation of the head node.
    pub fn update_head(&self, value: i32) {
        if let Some(node) = self.head.as_ref() {
            node.borrow_mut().value = value;
        }
    }
}

// ------------------------------------------------------------------
// Main
// ------------------------------------------------------------------
fn main() {
    let mut list = DoublyLinkedList::new();
    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    println!("Initial:");
    list.print_forward(); // 10 20 30

    list.increment_all(5);
    println!("After increment:");
    list.print_forward(); // 15 25 35

    list.update_head(100);
    println!("After head update:");
    list.print_forward(); // 100 25 35
}
