```rust
use std::cell::RefCell;
use std::rc::Rc;

// Internal link type
type Link<T> = Option<Rc<RefCell<Node<T>>>>;

// Internal node holding an Option<T> so we can safely extract
// the value out without requiring T: Default.
struct Node<T> {
    value: Option<T>,
    prev: Link<T>,
    next: Link<T>,
}

pub struct DoublyLinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front.
    /// We clone the current head Rc (no borrow), then borrow the head
    /// node only long enough to link back to the new node.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value: Some(value),
            prev: None,
            next: self.head.clone(),
        }));

        if let Some(head_rc) = self.head.as_ref() {
            head_rc.borrow_mut().prev = Some(new_node.clone());
        }

        self.head = Some(new_node.clone());
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
        self.len += 1;
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value: Some(value),
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(tail_rc) = self.tail.as_ref() {
            tail_rc.borrow_mut().next = Some(new_node.clone());
        }

        self.tail = Some(new_node.clone());
        if self.head.is_none() {
            self.head = Some(new_node);
        }
        self.len += 1;
    }

    /// Pop from the front.
    /// We clone the 'next' pointer under an immutable borrow, drop that
    /// borrow, then take the value out under a mutable borrow.
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;

        // 1. Capture the next node without holding a borrow into the update
        let next_rc = {
            let borrow = head_rc.borrow();
            borrow.next.clone()
        };

        // 2. Extract the value and sever the old head's links
        let value = {
            let mut borrow = head_rc.borrow_mut();
            borrow.prev = None;
            borrow.next = None;
            borrow.value.take()
        };

        // 3. Rewire the list
        if let Some(next_rc) = next_rc {
            next_rc.borrow_mut().prev = None;
            self.head = Some(next_rc);
        } else {
            self.tail = None;
        }

        self.len -= 1;
        value
    }

    /// Pop from the back.
    /// This is the one that usually fails: we must not hold a borrow on
    /// the tail while we try to borrow its previous node.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;

        // 1. Capture the previous node (clone Rc, no content borrow held)
        let prev_rc = {
            let borrow = tail_rc.borrow();
            borrow.prev.clone()
        };

        // 2. Extract value and clear the old tail's links
        let value = {
            let mut borrow = tail_rc.borrow_mut();
            borrow.prev = None;
