            old_head.borrow_mut().prev = Some(new_node.clone());
        }

        self.head = Some(new_node.clone());
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
        self.len += 1;
    }

    /// Push to the back. Similar strategy: clone `self.tail` for `prev`,
    /// borrow the old tail briefly to link its `next`.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value: Some(value),
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.as_ref() {
            old_tail.borrow_mut().next = Some(new_node.clone());
        }

        self.tail = Some(new_node.clone());
        if self.head.is_none() {
            self.head = Some(new_node);
        }
        self.len += 1;
    }

    /// Pop from the front. We clone the head pointer, read its `next`
    /// through a temporary borrow, unlink, then take the value.
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.as_ref()?.clone();
        let next = {
            // Borrow is dropped immediately after cloning the Rc.
            let b = old_head.borrow();
            b.next.clone()
