        match next {
            None => {
                self.head = None;
                self.tail = None;
            }
            Some(new_head) => {
                // Unlink: the new head should have no previous node.
                new_head.borrow_mut().prev = None;
                self.head = Some(new_head);
            }
        }

        self.len = self.len.saturating_sub(1);
        old_head.borrow_mut().value.take()
