use std::cell::RefCell;
use std::rc::Rc;

pub struct LinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. The borrow of the old head and new node are
    /// on separate `Rc`s, so `RefCell` allows both mut borrows.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        if let Some(old_head) = self.head.take() {
            // Link old head back to new node
            old_head.borrow_mut().prev = Some(new_node.clone());
            // Link new node forward to old head
            new_node.borrow_mut().next = Some(old_head);
        } else {
            // List was empty: new node is also the tail
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.take() {
            old_tail.borrow_mut().next = Some(new_node.clone());
            new_node.borrow_mut().prev = Some(old_tail);
        } else {
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    /// Pop from the front.
    /// We break the `next` link first (so the next node forgets us),
    /// then we can safely `try_unwrap` the old head.
    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|old_head_rc| {
            // Scope the borrow on old_head so it ends before we borrow neighbors
            let next_opt = {
                let mut old_ref = old_head_rc.borrow_mut();
                old_ref.next.take()
            };

            // If there is a new head, clear its `prev` pointer
            if let Some(ref next_rc) = next_opt {
                next_rc.borrow_mut().prev = None;
            } else {
                // List is now empty
                self.tail = None;
            }

            self.head = next_opt;
            self.len -= 1;

            // At this point old_head_rc should have exactly one strong reference
            // (the local one), because `self.head` was taken and `next.prev`
            // was cleared. `try_unwrap` lets us extract the value safely.
            Rc::try_unwrap(old_head_rc)
                .ok()
                .map(|cell| cell.into_inner().value)
        })
    }

    /// Pop from the back. Same strategy as pop_front, but in reverse.
    pub fn pop_back(&mut self) -> Option<T> {
        self.tail.take().map(|old_tail_rc| {
            let prev_opt = {
                let mut old_ref = old_tail_rc.borrow_mut();
                old_ref.prev.take()
            };

            if let Some(ref prev_rc) = prev_opt {
                prev_rc.borrow_mut().next = None;
