            self.len -= 1;

            // The temporary borrow from `.borrow_mut()` above is already dropped.
            // Because we detached both links, no other `Rc` references this node,
            // so `try_unwrap` succeeds and we can extract the value safely.
            Rc::try_unwrap(old_head).unwrap().into_inner().value
        })
    }

