    pub fn pop_back(&mut self) -> Option<T> {
        self.tail.take().map(|old_tail| {
            let prev = old_tail.borrow_mut().prev.take();

            match prev {
                Some(new_tail) => {
                    new_tail.borrow_mut().next = None;
                    self.tail = Some(new_tail);
                }
                None => {
                    self.head = None;
                }
            }

            self.len -= 1;

            Rc::try_unwrap(old_tail).unwrap().into_inner().value
        })
    }

