use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: Option<T>,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    // Peek at front (requires T: Clone)
    pub fn front(&self) -> Option<T>
    where
        T: Clone,
    {
        self.head.as_ref().and_then(|node| node.borrow().value.clone())
    }

    // Peek at back (requires T: Clone)
    pub fn back(&self) -> Option<T>
    where
        T: Clone,
    {
        self.tail.as_ref().and_then(|node| node.borrow().value.clone())
    }

    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value: Some(value),
            prev: None,
            next: self.head.clone(),
        }));

        // Link old head back to new node, if any
        if let Some(old_head) = self.head.as_ref() {
            old_head.borrow_mut().prev = Some(new_node.clone());
        } else {
            // List was empty -> tail is also this node
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value: Some(value),
            prev: None,
            next: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Link new node behind old tail
                new_node.borrow_mut().prev = Some(old_tail.clone());
                // Link old tail forward to new node
                old_tail.borrow_mut().next = Some(new_node.clone());
                self.tail = Some(new_node);
            }
            None => {
                // List was empty
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }

        self.len += 1;
    }

    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;

        // Read the next pointer *before* we borrow mutably later
        let next_rc = {
            let head_borrow = head_rc.borrow();
            head_borrow.next.clone()
        };

        if let Some(next) = next_rc {
            // Break backward link from new head
            next.borrow_mut().prev = None;
            self.head = Some(next);
        } else {
            // This was the only element
            self.tail = None;
        }

        self.len -= 1;
        // Take the value out of the removed node
        head_rc.borrow_mut().value.take()
    }

    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;

        // Read previous pointer before we borrow mutably later
        let prev_rc = {
            let tail_borrow = tail_rc.borrow();
            tail_borrow.prev.clone()
        };

        if let Some(prev) = prev_rc {
            // Break forward link from new tail
            prev.borrow_mut().next = None;
            self.tail = Some(prev);
        } else {
            // This was the only element
            self.head = None;
        }

        self.len -= 1;
        tail_rc.borrow_mut().value.take()
    }

    pub fn clear(&mut self) {
        self.head = None;
        self.tail = None;
        self.len = 0;
        // The Rc chain drops linearly without cycles
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        // Explicitly drop head/tail so the chain unwinds cleanly.
        // (Not strictly required, but makes the cleanup explicit.)
        self.clear();
    }
}

// ------------------------------------------------------------------
// Demonstration / sanity check
// ------------------------------------------------------------------
fn main() {
    let mut list = DoublyLinkedList::new();

    // Push both directions
    list.push_front(10); // 10
    list.push_back(20);  // 10 <-> 20
    list.push_front(5);  // 5 <-> 10 <-> 20
    list.push_back(30);  // 5 <-> 10 <-> 20 <-> 30

    assert_eq!(list.len(), 4);
    assert_eq!(list.front(), Some(5));
    assert_eq!(list.back(), Some(30));

    // Pop from both ends repeatedly
    assert_eq!(list.pop_front(), Some(5));
    assert_eq!(list.pop_back(), Some(30));
    assert_eq!(list.pop_front(), Some(10));
    assert_eq!(list.pop_back(), Some(20));

    assert!(list.is_empty());
    assert_eq!(list.pop_front(), None);
    assert_eq!(list.pop_back(), None);

    println!("All assertions passed. List works correctly.");
}
```

