use std::rc::Rc;
use std::cell::RefCell;

struct Node<T> {
    value: Option<T>,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value: Some(value),
            prev: None,
            next: self.head.clone(),
        }));

        match self.head.as_ref() {
            Some(old_head) => {
                old_head.borrow_mut().prev = Some(new_node.clone());
            }
            None => {
                self.tail = Some(new_node.clone());
            }
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value: Some(value),
            prev: None,
            next: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                new_node.borrow_mut().prev = Some(old_tail.clone());
                old_tail.borrow_mut().next = Some(new_node.clone());
                self.tail = Some(new_node);
            }
            None => {
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }

        self.len += 1;
    }

    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;
        let next_rc = {
            let head_borrow = head_rc.borrow();
            head_borrow.next.clone()
        };

        if let Some(next) = next_rc {
            next.borrow_mut().prev = None;
            self.head = Some(next);
        } else {
            self.tail = None;
        }

        self.len -= 1;
        Some(head_rc.borrow_mut().value.take()?)
    }

    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;
        let prev_rc = {
            let tail_borrow = tail_rc.borrow();
            tail_borrow.prev.clone()
        };

        if let Some(prev) = prev_rc {
            prev.borrow_mut().next = None;
            self.tail = Some(prev);
        } else {
            self.head = None;
        }

        self.len -= 1;
        Some(tail_rc.borrow_mut().value.take()?)
    }
}

