use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Node<T> {
    value: T,
    next: Option<Rc<RefCell<Node<T>>>>,
    prev: Option<Weak<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: self.head.clone(),
            prev: None,
        }));

        if let Some(old_head) = self.head.as_ref() {
            old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
        } else {
            self.tail = Some(Rc::clone(&new_node));
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: self.tail.as_ref().map(|t| Rc::downgrade(t)),
        }));

        if let Some(old_tail) = self.tail.as_ref() {
            old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
        } else {
            self.head = Some(Rc::clone(&new_node));
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;

        let next_rc = {
            let borrow = old_head.borrow();
            borrow.next.clone()
        };

        if let Some(next) = next_rc {
            next.borrow_mut().prev = None;
            self.head = Some(next);
        } else {
            self.head = None;
            self.tail = None;
        }

        self.len -= 1;
        Rc::try_unwrap(old_head).ok().map(|cell| cell.into_inner().value)
    }

    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;

        let prev_rc = {
            let borrow = old_tail.borrow();
            borrow.prev.as_ref().and_then(|w| w.upgrade())
        };

        if let Some(prev) = prev_rc {
            prev.borrow_mut().next = None;
            self.tail = Some(prev);
        } else {
            self.tail = None;
            self.head = None;
        }

        self.len -= 1;
        Rc::try_unwrap(old_tail).ok().map(|cell| cell.into_inner().value)
    }

    pub fn front(&self) -> Option<T>
    where
        T: Clone,
    {
        self.head.as_ref().map(|node| node.borrow().value.clone())
    }

    pub fn back(&self) -> Option<T>
    where
        T: Clone,
    {
        self.tail.as_ref().map(|node| node.borrow().value.clone())
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

