            self.tail = Some(prev_rc);
        } else {
            self.head = None;
        }

        self.len -= 1;
        Some(value)
    }

    pub fn front(&self) -> Option<i32> {
        self.head.as_ref().map(|n| n.borrow().value)
    }

    pub fn back(&self) -> Option<i32> {
        self.tail.as_ref().map(|n| n.borrow().value)
    }
}

