use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct Deque<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> Deque<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front.
    /// We clone the old head pointer out of a temporary borrow,
    /// so we can borrow the old head mutably without conflict.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            // Take the current head (if any) to become our `next`
            next: self.head.take(),
        }));

        // Clone the Rc pointer to the old head, then drop the borrow immediately
        let old_head_opt: Option<Rc<RefCell<Node<T>>>> = {
            let borrow = new_node.borrow();
            borrow.next.clone()
        };

        if let Some(old_head) = old_head_opt {
            // Now we can safely borrow the old head mutably
            old_head.borrow_mut().prev = Some(new_node.clone());
        } else {
            // List was empty, so new_node is also the tail
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.take(),
            next: None,
        }));

        // Clone the Rc pointer to the old tail
        let old_tail_opt: Option<Rc<RefCell<Node<T>>>> = {
            let borrow = new_node.borrow();
            borrow.prev.clone()
        };

        if let Some(old_tail) = old_tail_opt {
            old_tail.borrow_mut().next = Some(new_node.clone());
        } else {
            // List was empty
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    /// Pop from the front.
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;

        // Read and clone the `next` pointer, then drop the borrow
        let next_opt = {
            let borrow = head_rc.borrow();
            borrow.next.clone()
        };

        if let Some(next) = next_opt.as_ref() {
            // Break the back-link from the new head
            next.borrow_mut().prev = None;
        } else {
            // We just removed the only node
            self.tail = None;
        }

        self.head = next_opt;
        self.len -= 1;

        // At this point the only reference to `head_rc` is our local variable,
        // because we broke both the list head and the neighbor's back-link.
        let node = Rc::try_unwrap(head_rc).ok()?;
        Some(node.into_inner().value)
    }

    /// Pop from the back.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;

        // Read and clone the `prev` pointer
        let prev_opt = {
            let borrow = tail_rc.borrow();
            borrow.prev.clone()
        };

        if let Some(prev) = prev_opt.as_ref() {
