            prev.borrow_mut().next = None;
        } else {
            // We just removed the only node
            self.head = None;
        }

        self.tail = prev_opt;
        self.len -= 1;

        // The old tail is now only owned by `tail_rc`
        let node = Rc::try_unwrap(tail_rc).ok()?;
        Some(node.into_inner().value)
    }

    /// Drain the list on drop to avoid leaking the internal Rc chain.
    fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }
}

impl<T> Drop for Deque<T> {
    fn drop(&mut self) {
        self.clear();
    }
}

fn main() {
