    list.push_front(10);
    list.push_back(20);
    list.push_front(5);

    println!("Length: {}", list.len()); // 3

    while let Some(v) = list.pop_back() {
        println!("Popped back: {}", v);
    }

    println!("Empty? {}", list.is_empty()); // true
}
