```rust
use std::cell::RefCell;
use std::rc::Rc;

pub struct Node<T> {
    data: T,
    next: Option<Rc<RefCell<Node<T>>>>,
    prev: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. We take the current head out, link it behind
    /// the new node, then make the new node the head.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            data: value,
            next: None,
            prev: None,
        }));

        match self.head.take() {
            Some(old_head) => {
                // Link old head behind the new node.
                old_head.borrow_mut().prev = Some(Rc::clone(&new_node));
                new_node.borrow_mut().next = Some(old_head);
                self.head = Some(new_node);
            }
            None => {
                // Empty list: this is both head and tail.
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Push to the back. Symmetric to push_front.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            data: value,
            next: None,
            prev: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                // Link old tail in front of the new node.
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
                new_node.borrow_mut().prev = Some(old_tail);
                self.tail = Some(new_node);
            }
            None => {
                // Empty list.
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Pop from the front. We take the head out, clear the next node's
    /// `prev` pointer, then update `self.head`. Once all references are
    /// severed, `Rc::try_unwrap` gives us the node so we can move `data`.
    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|old_head_rc| {
            // Scope 1: borrow old head just long enough to steal its `next`.
            let next_rc = {
                let mut borrow = old_head_rc.borrow_mut();
                borrow.next.take()
            };

            match next_rc {
                Some(new_head_rc) => {
                    // Scope 2: borrow the new head to clear its back-link.
                    new_head_rc.borrow_mut().prev = None;
                    self.head = Some(new_head_rc);
                }
                None => {
                    // List had only one element.
                    self.tail = None;
                }
            }
            self.len -= 1;

            // At this point old_head_rc should be the only reference.
            Rc::try_unwrap(old_head_rc)
                .ok()
                .map(|cell| cell.into_inner().data)
        })
    }

    /// Pop from the back. Symmetric to pop_front.
    pub fn pop_back(&mut self) -> Option<T> {
        self.tail.take().map(|old_tail_rc| {
            // Scope 1: borrow old tail just long enough to steal its `prev`.
            let prev_rc = {
                let mut borrow = old_tail_rc.borrow_mut();
                borrow.prev.take()
            };

            match prev_rc {
                Some(new_tail_rc) => {
                    // Scope 2: borrow the new tail to clear its forward-link.
                    new_tail_rc.borrow_mut().next = None;
                    self.tail = Some(new_tail_rc);
                }
                None => {
                    // List had only one element.
                    self.head = None;
                }
            }
            self.len -= 1;

            // Severed all links; extract data.
            Rc::try_unwrap(old_tail_rc)
                .ok()
                .map(|cell| cell.into_inner().data)
        })
    }

    /// Non-consuming peek at the front node (clone of the Rc).
    pub fn peek_front(&self) -> Option<Rc<RefCell<Node<T>>>> {
        self.head.as_ref().map(Rc::clone)
    }

    /// Non-consuming peek at the back node.
    pub fn peek_back(&self) -> Option<Rc<RefCell<Node<T>>>> {
        self.tail.as_ref().map(Rc::clone)
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for DoublyLinkedList<T> {
    /// Without this, the nodes form a linear chain of references that
    /// never reach zero, so the nodes leak. We manually pop until empty.
    fn drop(&mut self) {
        while self.pop_front().is_some() {}
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    // Build: [0, 1, 2]
    list.push_back(1);
    list.push_back(2);
    list.push_front(0);

    assert_eq!(list.len(), 3);

    // Pop front -> 0, list is [1, 2]
    assert_eq!(list.pop_front(), Some(0));

    // Pop back  -> 2, list is [1]
    assert_eq!(list.pop_back(), Some(2));

    // Pop front -> 1, list empty
    assert_eq!(list.pop_front(), Some(1));
    assert!(list.is_empty());

    // Edge cases on empty list
    assert_eq!(list.pop_front(), None);
    assert_eq!(list.pop_back(), None);

    // Single element round-trip
    list.push_back(42);
    assert_eq!(list.peek_front().unwrap().borrow().data, 42);
    assert_eq!(list.peek_back().unwrap().borrow().data, 42);
    assert_eq!(list.pop_back(), Some(42));
    assert!(list.is_empty());

    println!("All safe-Rust doubly-linked list checks passed.");
}
