use std::cell::RefCell;
use std::rc::Rc;

pub struct Node<T> {
    val: T,
    next: Option<Rc<RefCell<Node<T>>>>,
    prev: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front.
    /// We borrow `old_head` and `new_node` separately — never simultaneously.
    pub fn push_front(&mut self, val: T) {
        let new_node = Rc::new(RefCell::new(Node {
            val,
            next: self.head.clone(), // may be None
            prev: None,
        }));

        match self.head.take() {
            Some(old_head) => {
                // Link old_head back to new_node
                old_head.borrow_mut().prev = Some(Rc::clone(&new_node));
                // Link new_node forward to old_head
                new_node.borrow_mut().next = Some(old_head);
                self.head = Some(new_node);
            }
            None => {
                // List was empty; new_node is both head and tail
                self.tail = Some(Rc::clone(&new_node));
                self.head = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Push to the back.
    pub fn push_back(&mut self, val: T) {
        let new_node = Rc::new(RefCell::new(Node {
            val,
            next: None,
            prev: self.tail.clone(),
        }));

        match self.tail.take() {
            Some(old_tail) => {
                old_tail.borrow_mut().next = Some(Rc::clone(&new_node));
                new_node.borrow_mut().prev = Some(old_tail);
                self.tail = Some(new_node);
            }
            None => {
                self.head = Some(Rc::clone(&new_node));
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Pop from the front.
    /// We clone `next` inside a short borrow, drop the borrow,
    /// then mutate `new_head`. Finally we `try_unwrap` only after
    /// the link back to `old_head` has been cleared.
    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|old_head| {
            let next = {
                // Short-lived immutable borrow just to read the pointer
                let h = old_head.borrow();
                h.next.clone()
            };

            match next {
                Some(new_head) => {
                    new_head.borrow_mut().prev = None; // break back-link
                    self.head = Some(new_head);
                }
                None => {
                    self.tail = None; // list is now empty
                }
            }

            self.len -= 1;

            // At this point only `old_head` (this variable) holds the Rc.
            Rc::try_unwrap(old_head)
                .ok()
                .map(|node| node.into_inner().val)
        })
    }

    /// Pop from the back.
    /// Same pattern: read `prev` in a scoped borrow, break the link,
    /// then unwrap.
    pub fn pop_back(&mut self) -> Option<T> {
        self.tail.take().map(|old_tail| {
            let prev = {
                let t = old_tail.borrow();
                t.prev.clone()
            };

            match prev {
                Some(new_tail) => {
                    new_tail.borrow_mut().next = None; // break forward link
                    self.tail = Some(new_tail);
                }
                None => {
                    self.head = None; // list is now empty
                }
            }

            self.len -= 1;

            Rc::try_unwrap(old_tail)
                .ok()
                .map(|node| node.into_inner().val)
        })
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

/// Critical: without this, the bidirectional `Rc` pointers form cycles
/// and the nodes are never freed (memory leak).
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        while self.pop_front().is_some() {}
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_front(10);
    list.push_front(20);
    list.push_back(30);
    list.push_back(40);

    println!("Length: {}", list.len()); // 4

