    println!("Pop back: {:?}", list.pop_back()); // Some(30)
    println!("Pop front: {:?}", list.pop_front()); // Some(20)

    println!("Remaining length: {}", list.len()); // 1
    println!("Pop front: {:?}", list.pop_front()); // Some(10)
    println!("Is empty? {}", list.is_empty()); // true
