use std::cell::RefCell;
use std::rc::Rc;

struct Node {
    value: i32,
    prev: Option<Rc<RefCell<Node>>>,
    next: Option<Rc<RefCell<Node>>>,
}

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
    len: usize,
}

impl Default for DoublyLinkedList {
    fn default() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push_front(&mut self, value: i32) {
        // Initialize the new node's 'next' to the current head
        // BEFORE we take the head away.
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        match self.head.take() {
            Some(old_head) => {
                // Link the old head back to the new node.
                old_head.borrow_mut().prev = Some(new_node.clone());
                self.head = Some(new_node);
            }
            None => {
                // List was empty; this node is both head and tail.
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                old_tail.borrow_mut().next = Some(new_node.clone());
                self.tail = Some(new_node);
            }
            None => {
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    pub fn pop_front(&mut self) -> Option<i32> {
        let old_head = self.head.take()?;
        let value = old_head.borrow().value;

        // Extract the next pointer in a tight scope so the borrow
        // on old_head is dropped before we borrow the neighbor.
        let next = {
            let borrow = old_head.borrow();
            borrow.next.clone()
        };

        if let Some(new_head) = next {
            new_head.borrow_mut().prev = None;
            self.head = Some(new_head);
        } else {
            // This was the only element.
            self.tail = None;
        }

        self.len -= 1;
        Some(value)
