    pub fn pop_back(&mut self) -> Option<i32> {
        let old_tail = self.tail.take()?;
        let value = old_tail.borrow().value;

        let prev = {
            let borrow = old_tail.borrow();
            borrow.prev.clone()
        };

        if let Some(new_tail) = prev {
            new_tail.borrow_mut().next = None;
            self.tail = Some(new_tail);
        } else {
            self.head = None;
        }

        self.len -= 1;
        Some(value)
    }
