use std::cell::RefCell;
use std::rc::Rc;

/// Internal node. Both directions use `Rc` (not `Weak`) as requested,
/// so we must break cycles in `Drop`.
struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        // Scope the borrow: borrow old head, update its prev pointer, then drop borrow.
        if let Some(old_head) = self.head.clone() {
            old_head.borrow_mut().prev = Some(new_node.clone());
        } else {
            // List was empty; new node is also the tail.
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.clone() {
            old_tail.borrow_mut().next = Some(new_node.clone());
        } else {
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    /// Pop from the front.
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;
        let next = {
            // Tight scope: borrow only to clone the `next` pointer.
            let node = old_head.borrow();
            node.next.clone()
        };

        self.head = next.clone();
        if let Some(new_head) = next {
            new_head.borrow_mut().prev = None;
        } else {
            self.tail = None;
        }

        self.len -= 1;

        // At this point `old_head` should have exactly one owner (`old_head` itself).
        Rc::try_unwrap(old_head)
            .expect("node should have unique ownership after unlinking")
            .into_inner()
            .value
            .pipe(|v| Some(v)) // just to keep it readable; actually unwrap above gives T
    }

    /// Pop from the back.
    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;
        let prev = {
            let node = old_tail.borrow();
            node.prev.clone()
        };

        self.tail = prev.clone();
        if let Some(new_tail) = prev {
            new_tail.borrow_mut().next = None;
        } else {
            self.head = None;
        }

        self.len -= 1;

        Rc::try_unwrap(old_tail)
            .expect("node should have unique ownership after unlinking")
            .into_inner()
            .value
            .pipe(|v| Some(v))
    }

    /// Clear the list by replacing ourselves and letting `Drop` clean up.
    pub fn clear(&mut self) {
        *self = Self::new();
    }
}

// We must break the node-to-node cycles manually, or the nodes leak.
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        let mut current = self.head.take();
        self.tail = None;

        while let Some(node) = current {
            // Borrow the node, take its `next`, clear its `prev`, then drop borrow.
            let mut node_ref = node.borrow_mut();
            let next = node_ref.next.take();
            node_ref.prev = None;
            drop(node_ref); // explicit drop of borrow before we recurse
            current = next;
        }
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

