use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. We clone the current head Rc *before* we borrow
    /// anything mutably, so the borrow checker (at runtime) never conflicts.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(), // clone the pointer, don't borrow yet
        }));

        match self.head.take() {
            Some(old_head) => {
                // Borrow the *old* head mutably to point it back at us
                old_head.borrow_mut().prev = Some(new_node.clone());
                self.head = Some(new_node);
            }
            None => {
                // List was empty: new node is both head and tail
                self.tail = Some(new_node.clone());
                self.head = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Push to the back (symmetric logic).
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        match self.tail.take() {
            Some(old_tail) => {
                old_tail.borrow_mut().next = Some(new_node.clone());
                self.tail = Some(new_node);
            }
            None => {
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Pop from the front.
    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|old_head| {
            // Immutably borrow just long enough to clone the next pointer
            let next = old_head.borrow().next.clone();

            match next {
                Some(next_node) => {
                    // Break the back-link from the new head back to us
                    next_node.borrow_mut().prev = None;
                    self.head = Some(next_node);
                }
                None => {
                    // We removed the only element
                    self.tail = None;
                }
            }

            self.len -= 1;

            // At this point old_head's Rc count is exactly 1:
            // - self.head no longer holds it (we .take()'d)
            // - next_node.prev no longer holds it (we set it to None)
            Rc::try_unwrap(old_head).ok().map(|node| node.into_inner().value)
        })
    }

    /// Pop from the back — this is the one that usually causes borrow issues.
    /// The pattern is: clone prev -> break forward-link -> unwrap.
    pub fn pop_back(&mut self) -> Option<T> {
        self.tail.take().map(|old_tail| {
            // Clone the previous node's pointer before any mutable borrows
            let prev = old_tail.borrow().prev.clone();

            match prev {
                Some(prev_node) => {
                    // Break the forward-link so prev no longer references old_tail
                    prev_node.borrow_mut().next = None;
                    self.tail = Some(prev_node);
                }
                None => {
                    // We removed the only element
                    self.head = None;
                }
            }

            self.len -= 1;

            // Reference count is now 1, so unwrap succeeds safely
            Rc::try_unwrap(old_tail).ok().map(|node| node.into_inner().value)
        })
    }

    /// Peek at front (requires T: Clone).
    pub fn front(&self) -> Option<T>
    where
        T: Clone,
    {
        self.head.as_ref().map(|node| node.borrow().value.clone())
    }

    /// Peek at back.
    pub fn back(&self) -> Option<T>
    where
        T: Clone,
    {
        self.tail.as_ref().map(|node| node.borrow().value.clone())
    }
}

/// Critical: without this, the nodes form a reference cycle (A <-> B) and
/// are never freed when the list is dropped.
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        while self.pop_front().is_some() {}
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_front(10);
    list.push_back(20);
    list.push_front(5);

    println!("Length: {}", list.len()); // 3
    println!("Front: {:?}", list.front()); // Some(5)
    println!("Back: {:?}", list.back());  // Some(20)

    assert_eq!(list.pop_front(), Some(5));
    assert_eq!(list.pop_back(), Some(20));
    assert_eq!(list.pop_back(), Some(10));
    assert_eq!(list.pop_back(), None); // empty
}
```

### Why the borrow checker stops complaining

The classic pitfall is trying to do something like:

```rust
