        // Take ownership of the head Rc from self.
        let head_rc = self.head.take()?;

        // Borrow briefly inside a block so the borrow ends before we touch `self`.
        let (next_rc, value) = {
            let mut borrow = head_rc.borrow_mut();
            (borrow.next.take(), borrow.value.take())
