    /// 1. Take the head out of `self.head`.
    /// 2. Borrow it briefly to clone its `next` pointer.
    /// 3. Clear the `prev` pointer on the new head.
    /// 4. Update `self.head` (and `self.tail` if list is now empty).
    /// 5. Only now can we `try_unwrap` the old head because its back-link is broken.
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;

        let next_rc = {
            let borrow = old_head.borrow();
            borrow.next.clone()
        };

        // Break the link from the new head back to the old head
        if let Some(ref next) = next_rc {
            next.borrow_mut().prev = None;
        }

        self.head = next_rc.clone();
        if self.head.is_none() {
            self.tail = None;
        }

        self.len -= 1;

        Rc::try_unwrap(old_head)
            .ok()
            .map(|cell| cell.into_inner().value)
    }

    /// Pop from the back.
    /// Same pattern: break `prev`'s `next` pointer, update `self.tail`,
    /// then unwrap.
    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;

        let prev_rc = {
            let borrow = old_tail.borrow();
            borrow.prev.clone()
        };

        // Break the link from the new tail forward to the old tail
        if let Some(ref prev) = prev_rc {
            prev.borrow_mut().next = None;
        }

        self.tail = prev_rc.clone();
        if self.tail.is_none() {
            self.head = None;
        }

        self.len -= 1;

        Rc::try_unwrap(old_tail)
            .ok()
            .map(|cell| cell.into_inner().value)
    }

    /// Non-consuming peek (requires Clone for simplicity).
    pub fn front(&self) -> Option<T>
    where
        T: Clone,
    {
        self.head.as_ref().map(|n| n.borrow().value.clone())
    }

    pub fn back(&self) -> Option<T>
    where
        T: Clone,
    {
        self.tail.as_ref().map(|n| n.borrow().value.clone())
    }

    pub fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }
}

impl<T> Default for List<T> {
    fn default() -> Self {
        Self::new()
    }
}

