use std::rc::Rc;

struct Node {
    value: i32,
    prev: Option<Rc<RefCell<Node>>>,
    next: Option<Rc<RefCell<Node>>>,
}

pub struct DoublyLinkedList {
    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self { head: None, tail: None }
    }

    /// Push to the front. The key: clone `self.head` into the new node,
    /// then borrow the old head *only* to set its `prev`.
    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        // Borrow the old head mutably, but only inside this block.
        if let Some(ref old_head) = self.head {
            old_head.borrow_mut().prev = Some(new_node.clone());
        }

        self.head = Some(new_node.clone());
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
    }

    /// Push to the back (mirror logic).
    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(ref old_tail) = self.tail {
            old_tail.borrow_mut().next = Some(new_node.clone());
        }

        self.tail = Some(new_node.clone());
        if self.head.is_none() {
            self.head = Some(new_node);
        }
    }

    /// Pop from the back. We `take()` the tail `Rc`, clone its `prev` pointer,
    /// then borrow that previous node separately to sever its `next`.
    pub fn pop_back(&mut self) -> Option<i32> {
        self.tail.take().map(|tail_rc| {
            // All borrows on tail_rc are temporary.
            let value = tail_rc.borrow().value;
            let prev = tail_rc.borrow().prev.clone();

            // Now borrow the previous node (if any) to cut the link.
            if let Some(ref prev_rc) = prev {
                prev_rc.borrow_mut().next = None;
            }

            self.tail = prev;
            if self.tail.is_none() {
                self.head = None;
            }

            value
        })
    }

    /// Pop from the front (mirror logic).
    pub fn pop_front(&mut self) -> Option<i32> {
        self.head.take().map(|head_rc| {
            let value = head_rc.borrow().value;
            let next = head_rc.borrow().next.clone();

            if let Some(ref next_rc) = next {
                next_rc.borrow_mut().prev = None;
            }

            self.head = next;
            if self.head.is_none() {
                self.tail = None;
            }

            value
        })
    }

