/// Because nodes point to each other with `Rc`, dropping the list struct
/// alone would leave a cycle. We drain it explicitly.
impl Drop for DoublyLinkedList {
    fn drop(&mut self) {
        while self.pop_back().is_some() {}
    }
}

impl Default for DoublyLinkedList {
    fn default() -> Self {
        Self::new()
    }
}

