use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }

    /// Push to the front. Only borrows the old head briefly to wire `prev`.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        // Borrow the old head just long enough to point it back at us.
        if let Some(old_head) = self.head.as_ref() {
            old_head.borrow_mut().prev = Some(new_node.clone());
        }

        self.head = Some(new_node.clone());

        // If the list was empty, tail must also point here.
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
    }

    /// Push to the back. Symmetric to push_front.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.as_ref() {
            old_tail.borrow_mut().next = Some(new_node.clone());
        }

        self.tail = Some(new_node.clone());

        if self.head.is_none() {
            self.head = Some(new_node);
        }
    }

    /// Pop from the front. Break links first, then unwrap the detached node.
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;

        // Extract the `next` pointer and immediately drop the borrow.
        let next_rc = {
            let mut h = head_rc.borrow_mut();
            h.next.take()
        };

        if let Some(next) = next_rc {
            // The new head should have no predecessor.
            next.borrow_mut().prev = None;
            self.head = Some(next);
        } else {
            // We removed the only element.
            self.tail = None;
        }

        // At this point `head_rc` has count == 1 (all internal links cleared,
        // and `self.head` was taken). Unwrap is safe.
        Some(
            Rc::try_unwrap(head_rc)
                .expect("pop_front: head was still referenced elsewhere")
                .into_inner()
                .value,
        )
    }

    /// Pop from the back. This is the pattern that usually hits borrow-checker walls.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;

        // Extract `prev` and drop the borrow on the tail immediately.
        let prev_rc = {
            let mut t = tail_rc.borrow_mut();
            t.prev.take()
        };

        if let Some(prev) = prev_rc {
            // The new tail should have no successor.
            prev.borrow_mut().next = None;
            self.tail = Some(prev);
        } else {
            // We removed the only element.
            self.head = None;
        }

        Some(
            Rc::try_unwrap(tail_rc)
                .expect("pop_back: tail was still referenced elsewhere")
                .into_inner()
                .value,
        )
    }
}

fn main() {
