// ------------------------------------------------------------------
// Private node
// ------------------------------------------------------------------
struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

// ------------------------------------------------------------------
// DoublyLinkedList
// ------------------------------------------------------------------
pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    // ------------------------------------------------------------------
    // push_front
    // ------------------------------------------------------------------
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(), // point to old head
        }));

        // If there was an old head, wire it back to the new node
        if let Some(ref head) = self.head {
            head.borrow_mut().prev = Some(new_node.clone());
        } else {
            // List was empty: this is also the tail
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    // ------------------------------------------------------------------
    // push_back
    // ------------------------------------------------------------------
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(), // point to old tail
            next: None,
        }));

        if let Some(ref tail) = self.tail {
            tail.borrow_mut().next = Some(new_node.clone());
        } else {
            // List was empty: this is also the head
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    // ------------------------------------------------------------------
    // pop_front
    // ------------------------------------------------------------------
    pub fn pop_front(&mut self) -> Option<T> {
        // 1. Remove the head from the list
        let old_head = self.head.take()?;
        self.len -= 1;

        // 2. Read the next pointer (immutable borrow, then drop it)
        let next = {
            let borrow = old_head.borrow();
            borrow.next.clone()
