use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    // We store Option<T> so we can `.take()` the value out
    // without needing `T: Default` or `unsafe`.
    val: Option<T>,
    next: Option<Rc<RefCell<Node<T>>>>,
    prev: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push_front(&mut self, val: T) {
        let new_head = Rc::new(RefCell::new(Node {
            val: Some(val),
            next: self.head.clone(),
            prev: None,
        }));

        match self.head.clone() {
            Some(old_head) => {
                // Clone the Rc so we can borrow it mutably
                // without interfering with `self.head`.
                old_head.borrow_mut().prev = Some(new_head.clone());
            }
            None => {
                // List was empty; new node is also the tail.
                self.tail = Some(new_head.clone());
            }
        }

        self.head = Some(new_head);
        self.len += 1;
    }

    pub fn push_back(&mut self, val: T) {
        let new_tail = Rc::new(RefCell::new(Node {
            val: Some(val),
            next: None,
            prev: self.tail.clone(),
        }));

        match self.tail.clone() {
            Some(old_tail) => {
                old_tail.borrow_mut().next = Some(new_tail.clone());
            }
            None => {
                // List was empty; new node is also the head.
                self.head = Some(new_tail.clone());
            }
        }

        self.tail = Some(new_tail);
        self.len += 1;
    }

    pub fn pop_front(&mut self) -> Option<T> {
        // Move the head Rc out of the list.
        let old_head = self.head.take()?;

        // Clone the internal `next` pointer before we do any
        // mutable borrows. This keeps the borrow checker happy.
        let next = old_head.borrow().next.clone();

        // Unlink `old_head` and wire up the new head.
        match next.as_ref() {
            Some(new_head) => {
                new_head.borrow_mut().prev = None;
            }
            None => {
                // The list is now empty.
                self.tail = None;
            }
        }
        self.head = next;
        self.len -= 1;

        // At this point `old_head` is not borrowed by anyone
        // except this local variable, so we can take its value.
        let mut borrowed = old_head.borrow_mut();
        borrowed.val.take()
    }

    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;

        let prev = old_tail.borrow().prev.clone();

        match prev.as_ref() {
            Some(new_tail) => {
                new_tail.borrow_mut().next = None;
            }
            None => {
                self.head = None;
            }
        }
        self.tail = prev;
        self.len -= 1;

        let mut borrowed = old_tail.borrow_mut();
        borrowed.val.take()
    }

    /// Break all links so the `Rc` cycle is destroyed.
    pub fn clear(&mut self) {
        let mut current = self.head.take();
        while let Some(node) = current {
            let mut borrowed = node.borrow_mut();
            // Take ownership of the next link so this node
            // no longer references anything.
            current = borrowed.next.take();
            borrowed.prev = None;
            // `borrowed` drops here, then `node` drops,
            // freeing the isolated node.
        }
        self.tail = None;
        self.len = 0;
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

// Critical: without this, `prev` and `next` form a reference
// cycle that `Rc` cannot clean up automatically.
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        self.clear();
    }
}

