use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. The borrow checker is happy because we only
    /// borrow the old head briefly to update its `prev` pointer.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        if let Some(old_head) = self.head.as_ref() {
            old_head.borrow_mut().prev = Some(new_node.clone());
        } else {
            // List was empty; the new node is also the tail.
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.as_ref() {
            old_tail.borrow_mut().next = Some(new_node.clone());
        } else {
            // List was empty.
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    /// Pop from the front. We clone the `next` pointer inside a block,
    /// drop the borrow, then update the new head's `prev`.
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;
        let next_rc = {
            let borrowed = head_rc.borrow();
            borrowed.next.clone()
        };

        if let Some(next) = next_rc {
            next.borrow_mut().prev = None;
            self.head = Some(next);
        } else {
            // List is now empty.
            self.tail = None;
        }

        self.len -= 1;

        // At this point `head_rc` has exactly one strong reference
        // (held by our local variable), so try_unwrap succeeds.
        let node = Rc::try_unwrap(head_rc).ok()?;
        Some(node.into_inner().value)
    }

    /// Pop from the back. Same pattern: clone `prev` inside a block,
    /// drop the borrow, update the new tail's `next`, then unwrap.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;
        let prev_rc = {
            let borrowed = tail_rc.borrow();
            borrowed.prev.clone()
        };

        if let Some(prev) = prev_rc {
            prev.borrow_mut().next = None;
            self.tail = Some(prev);
        } else {
            // List is now empty.
            self.head = None;
        }

        self.len -= 1;

        let node = Rc::try_unwrap(tail_rc).ok()?;
        Some(node.into_inner().value)
    }

    pub fn front(&self) -> Option<T>
    where
        T: Clone,
    {
        self.head.as_ref().map(|node| node.borrow().value.clone())
    }

    pub fn back(&self) -> Option<T>
    where
        T: Clone,
    {
        self.tail.as_ref().map(|node| node.borrow().value.clone())
    }

    /// Break the cycle manually so we don't leak nodes.
    pub fn clear(&mut self) {
        while self.pop_back().is_some() {}
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        // Without this, the mutual `prev`/`next` Rc pointers create
        // a reference cycle and leak memory.
        self.clear();
    }
}

