```rust
use std::cell::RefCell;
use std::rc::Rc;

pub struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }

    /// Push to the front.
    /// Pattern: clone the Rc out of self.head before borrowing.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        // Borrow the old head through its own Rc, not through `self`.
        if let Some(old_head) = self.head.clone() {
            old_head.borrow_mut().prev = Some(new_node.clone());
        }

        self.head = Some(new_node.clone());
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
    }

    /// Push to the back.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.clone() {
            old_tail.borrow_mut().next = Some(new_node.clone());
        }

        self.tail = Some(new_node.clone());
        if self.head.is_none() {
            self.head = Some(new_node);
        }
    }

    /// Pop from the front.
    /// We clone out the Rc references we need, then drop borrows
    /// before we reassign `self.head`.
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;

        // Clone the next pointer while borrowing head_rc.
        let next_rc = {
            let head_borrow = head_rc.borrow();
            head_borrow.next.clone()
        };

        if let Some(next_rc) = next_rc {
            // Break the back-link from the new head.
            next_rc.borrow_mut().prev = None;
            self.head = Some(next_rc);
        } else {
            // Was the only node.
            self.tail = None;
        }

        // At this point head_rc has exactly one strong reference
        // (our local `head_rc`), because:
        // - self.head was taken
        // - next_rc.prev was cleared
        // So try_unwrap will always succeed in correct usage.
        Some(
            Rc::try_unwrap(head_rc)
                .expect("head reference count should be 1")
                .into_inner()
                .value,
        )
    }

    /// Pop from the back.
    /// Same cloning pattern: never borrow `self.tail` and then
    /// try to write to `self.tail`.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;

        let prev_rc = {
            let tail_borrow = tail_rc.borrow();
            tail_borrow.prev.clone()
        };

        if let Some(prev_rc) = prev_rc {
            // Break the forward-link from the new tail.
            prev_rc.borrow_mut().next = None;
            self.tail = Some(prev_rc);
        } else {
            // Was the only node.
            self.head = None;
        }

        Some(
            Rc::try_unwrap(tail_rc)
                .expect("tail reference count should be 1")
                .into_inner()
                .value,
        )
    }

    pub fn peek_front(&self) -> Option<T>
    where
        T: Clone,
    {
        self.head.as_ref().map(|n| n.borrow().value.clone())
    }

    pub fn peek_back(&self) -> Option<T>
    where
        T: Clone,
    {
        self.tail.as_ref().map(|n| n.borrow().value.clone())
    }

    /// Safe traversal using cloned Rc pointers.
    pub fn len(&self) -> usize {
        let mut count = 0;
        let mut current = self.head.clone();
        while let Some(node) = current {
            count += 1;
            let next = node.borrow().next.clone();
            current = next;
        }
        count
    }

    pub fn clear(&mut self) {
        // Drop references iteratively to avoid deep recursion.
        while self.pop_front().is_some() {}
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    // Build: 3 -> 2 -> 1 (front is left)
    list.push_front(1);
    list.push_front(2);
    list.push_front(3);

    assert_eq!(list.len(), 3);
    assert_eq!(list.peek_front(), Some(3));
    assert_eq!(list.peek_back(), Some(1));

    assert_eq!(list.pop_back(), Some(1));
    assert_eq!(list.pop_front(), Some(3));

    // Now list should contain only [2]
    assert_eq!(list.len(), 1);
    assert_eq!(list.peek_front(), Some(2));
    assert_eq!(list.peek_back(), Some(2));

    assert_eq!(list.pop_back(), Some(2));
    assert!(list.is_empty());

    // Push back to empty list
    list.push_back(42);
    assert_eq!(list.peek_front(), Some(42));
    assert_eq!(list.peek_back(), Some(42));

    println!("All assertions passed. List works correctly.");
}

#[cfg(test)]
