use std::cell::{RefCell, Ref};
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Add to the front.
    pub fn push_front(&mut self, value: T) {
        let new_head = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(), // clone handle, don't borrow yet
        }));

        if let Some(ref old_head) = self.head {
            // Borrow the old head mutably only after we have our new node ready
            old_head.borrow_mut().prev = Some(Rc::clone(&new_head));
        } else {
            // List was empty: tail is also this node
            self.tail = Some(Rc::clone(&new_head));
        }

        self.head = Some(new_head);
        self.len += 1;
    }

    /// Add to the back.
    pub fn push_back(&mut self, value: T) {
        let new_tail = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(ref old_tail) = self.tail {
            old_tail.borrow_mut().next = Some(Rc::clone(&new_tail));
        } else {
            self.head = Some(Rc::clone(&new_tail));
        }

        self.tail = Some(new_tail);
        self.len += 1;
    }

    /// Remove and return the front value.
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;

        // Clone the next pointer through a temporary borrow
        let next = old_head.borrow().next.clone();

        // Rewire the list
        self.head = next;
        if let Some(ref head) = self.head {
            head.borrow_mut().prev = None;
        } else {
            self.tail = None;
        }

        self.len -= 1;

        // At this point no other Rc references old_head (we cleared its back-link).
        // try_unwrap succeeds because the node's strong count is exactly 1.
        let node = Rc::try_unwrap(old_head)
            .expect("pop_front failed: unexpected external Rc reference to node");
        Some(node.into_inner().value)
    }

    /// Remove and return the back value.
    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;

        let prev = old_tail.borrow().prev.clone();

        self.tail = prev;
        if let Some(ref tail) = self.tail {
            tail.borrow_mut().next = None;
        } else {
            self.head = None;
        }

        self.len -= 1;

        let node = Rc::try_unwrap(old_tail)
            .expect("pop_back failed: unexpected external Rc reference to node");
        Some(node.into_inner().value)
    }

    /// Peek at the front value without removing it.
    /// Returns a borrow guard so no extra Rc clones are exposed.
    pub fn front(&self) -> Option<Ref<'_, T>> {
        self.head.as_ref().map(|node_rc| {
            Ref::map(node_rc.borrow(), |node| &node.value)
        })
    }

    /// Peek at the back value.
    pub fn back(&self) -> Option<Ref<'_, T>> {
        self.tail.as_ref().map(|node_rc| {
            Ref::map(node_rc.borrow(), |node| &node.value)
        })
    }

    /// Drain the list (required to break Rc cycles on drop).
    pub fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        // Breaking the links iteratively prevents an Rc reference cycle
        // between prev/next nodes.
        self.clear();
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_front(1);
    list.push_back(2);
    list.push_front(0);

    assert!(list.len() == 3);
    assert_eq!(*list.front().unwrap(), 0);
    assert_eq!(*list.back().unwrap(), 2);

    assert_eq!(list.pop_front(), Some(0));
    assert_eq!(list.pop_back(), Some(2));
    assert_eq!(list.pop_back(), Some(1));
    assert_eq!(list.pop_back(), None);

    assert!(list.is_empty());

    // Verify Drop doesn't leak (run with valgrind / Miri if you want,
    // but the explicit clear guarantees no cycle remains).
    println!("All safe Rust assertions passed.");
}

