    /// 2. Read its `next` (temporary borrow, immediately dropped).
    /// 3. Unlink `next.prev`.
    /// 4. Move `self.head` to the next node (and clear tail if list emptied).
    /// 5. Once unlinked, `try_unwrap` should succeed (strong_count == 1).
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;

        let next_rc = head_rc.borrow().next.clone();
