        if let Some(next) = next_rc.as_ref() {
            next.borrow_mut().prev = None;
        }

        self.head = next_rc;
        if self.head.is_none() {
            self.tail = None;
        }
        self.len -= 1;

        Rc::try_unwrap(head_rc)
            .ok()
            .map(|cell| cell.into_inner().value)
