use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. We clone the `Rc` pointers *before* we borrow
    /// anything mutably, so the borrow checker (and `RefCell`) stay happy.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(), // clone pointer, don't borrow
        }));

        // Borrow the old head *only* to patch its `prev` pointer.
        // The borrow is dropped immediately after this block.
        if let Some(ref old_head) = self.head {
            old_head.borrow_mut().prev = Some(new_node.clone());
        }

        self.head = Some(new_node);
        if self.tail.is_none() {
            self.tail = self.head.clone();
        }
        self.len += 1;
    }

    /// Push to the back. Same pattern: clone the tail pointer, borrow it
    /// briefly to update its `next`, then move the list's tail.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(ref old_tail) = self.tail {
            old_tail.borrow_mut().next = Some(new_node.clone());
        }

        self.tail = Some(new_node.clone());
        if self.head.is_none() {
            self.head = Some(new_node);
        }
        self.len += 1;
    }

    /// Pop from the front. Critical steps:
    /// 1. Take the head `Rc` out of the list.
    /// 2. Clone its `next` pointer.
    /// 3. Update the list head and clear the new head's `prev`.
    /// 4. Only after the neighbor's `prev` is `None` can `try_unwrap`
    ///    succeed (no other strong references remain).
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;
        let next = old_head.borrow().next.clone(); // temporary borrow

        self.head = next.clone();
        if let Some(ref h) = self.head {
            h.borrow_mut().prev = None; // break back-link
        } else {
            self.tail = None;
        }

        self.len -= 1;

        // At this point `old_head` is only held by our local variable.
        Rc::try_unwrap(old_head)
            .ok()
            .map(|node_refcell| node_refcell.into_inner().value)
    }

    /// Pop from the back. Mirror image of `pop_front`.
    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;
        let prev = old_tail.borrow().prev.clone(); // temporary borrow

        self.tail = prev.clone();
        if let Some(ref t) = self.tail {
            t.borrow_mut().next = None; // break forward-link
        } else {
            self.head = None;
        }

        self.len -= 1;

        Rc::try_unwrap(old_tail)
            .ok()
            .map(|node_refcell| node_refcell.into_inner().value)
    }

    /// Clears the list by repeatedly popping. This also serves as our
    /// `Drop` logic to avoid `Rc` cycles.
    pub fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }
}

// Prevent memory leaks: if the user drops the list, we break all internal
// links so the `Rc` nodes can be freed.
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        self.clear();
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_front(10);
    list.push_back(20);
    list.push_front(5);

    println!("len = {}", list.len()); // 3

    assert_eq!(list.pop_front(), Some(5));
    assert_eq!(list.pop_back(), Some(20));
    assert_eq!(list.pop_back(), Some(10));
    assert_eq!(list.pop_back(), None);
    assert!(list.is_empty());
}
