            if let Some(next) = next_rc.as_ref() {
                next.borrow_mut().prev = None;
            } else {
                self.tail = None;
            }

            self.head = next_rc;
            self.len -= 1;

            // At this point `prev` links from `next` are broken,
            // and `self.head` no longer points here. Try to take ownership.
            Rc::try_unwrap(head_rc).ok().map(|node_rc| node_rc.into_inner().value)
        })
    }

    /// Remove from the back.
    pub fn pop_back(&mut self) -> Option<T> {
        self.tail.take().map(|tail_rc| {
            // Scope the borrow to read `prev`.
            let prev_rc = {
                let tail_ref = tail_rc.borrow();
                tail_ref.prev.clone()
