            if let Some(prev) = prev_rc.as_ref() {
                prev.borrow_mut().next = None;
            } else {
                self.head = None;
            }

            self.tail = prev_rc;
            self.len -= 1;

            Rc::try_unwrap(tail_rc).ok().map(|node_rc| node_rc.into_inner().value)
        })
    }

    /// Empty the list using `pop_back`, which correctly breaks links.
    pub fn clear(&mut self) {
        while self.pop_back().is_some() {}
