use std::cell::{Ref, RefCell};
use std::rc::Rc;

// ------------------------------------------------------------------
// Internal node — never exposed to users, so we control all Rc refs.
// ------------------------------------------------------------------
struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

// ------------------------------------------------------------------
// Public list API
// ------------------------------------------------------------------
pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    // ------------------------------------------------------------------
    // push_front — clone Rc first so we don't borrow `self` mutably
    // while holding a borrow inside the Option.
    // ------------------------------------------------------------------
    pub fn push_front(&mut self, value: T) {
        let old_head = self.head.clone(); // clone Rc, don't borrow self
