            value,
            prev: None,
            next: old_head.clone(),
        }));

        if let Some(ref old) = old_head {
            old.borrow_mut().prev = Some(new_head.clone());
        } else {
            // List was empty: new node is also the tail
            self.tail = Some(new_head.clone());
        }

        self.head = Some(new_head);
        self.len += 1;
    }

    // ------------------------------------------------------------------
    // push_back — same pattern at the tail end.
    // ------------------------------------------------------------------
    pub fn push_back(&mut self, value: T) {
        let old_tail = self.tail.clone();
        let new_tail = Rc::new(RefCell::new(Node {
            value,
            prev: old_tail.clone(),
            next: None,
        }));

        if let Some(ref old) = old_tail {
            old.borrow_mut().next = Some(new_tail.clone());
        } else {
            // List was empty
            self.head = Some(new_tail.clone());
        }

        self.tail = Some(new_tail);
        self.len += 1;
    }

    // ------------------------------------------------------------------
    // pop_front — unlink head, clear the next node's prev, then unwrap
    // the old head (count is 1 because we cleared all internal links).
    // ------------------------------------------------------------------
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;
        let next = {
            let mut borrow = old_head.borrow_mut();
            borrow.next.take()
