        Rc::try_unwrap(old_head)
            .ok()
            .map(|cell| cell.into_inner().value)
    }

    // ------------------------------------------------------------------
    // pop_back — mirror image of pop_front.
    // ------------------------------------------------------------------
    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;
        let prev = {
            let mut borrow = old_tail.borrow_mut();
            borrow.prev.take()
        };

        if let Some(ref new_tail) = prev {
            new_tail.borrow_mut().next = None;
        } else {
            self.head = None;
        }

        self.tail = prev;
        self.len -= 1;

        Rc::try_unwrap(old_tail)
            .ok()
            .map(|cell| cell.into_inner().value)
    }

