    // Peek at ends — returns a borrow guard (`Ref<T>`) so users can't
    // accidentally clone internal Rcs.
    // ------------------------------------------------------------------
    pub fn front<'a>(&'a self) -> Option<Ref<'a, T>> {
        self.head.as_ref().map(|node| {
            Ref::map(node.borrow(), |n| &n.value)
        })
    }

    pub fn back<'a>(&'a self) -> Option<Ref<'a, T>> {
        self.tail.as_ref().map(|node| {
            Ref::map(node.borrow(), |n| &n.value)
        })
    }

    pub fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }
}

