    fn default() -> Self {
        Self::new()
    }
}

// ------------------------------------------------------------------
// Critical: break the Rc cycle on drop so nodes are actually freed.
// ------------------------------------------------------------------
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        while let Some(_) = self.pop_front() {}
