```rust
use std::cell::RefCell;
use std::rc::Rc;

pub struct List<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

struct Node<T> {
    value: T,
    next: Option<Rc<RefCell<Node<T>>>>,
    prev: Option<Rc<RefCell<Node<T>>>>,
}

impl<T> List<T> {
    pub fn new() -> Self {
        List { head: None, tail: None, len: 0 }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. We clone the old head Rc, borrow the old node
    /// mutably (to set its prev), drop that borrow, then borrow the new node.
    pub fn push_front(&mut self, value: T) {
        let old_head = self.head.take();
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: old_head.clone(),
            prev: None,
        }));

        if let Some(ref old) = old_head {
            // Borrow old head, set its back-pointer to the new node, then drop borrow.
            old.borrow_mut().prev = Some(new_node.clone());
            // Now borrow the new node separately to set its forward pointer.
            new_node.borrow_mut().next = Some(old.clone());
        }

        self.head = Some(new_node.clone());
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
        self.len += 1;
    }

    /// Push to the back (mirror of push_front).
    pub fn push_back(&mut self, value: T) {
        let old_tail = self.tail.take();
        let new_node = Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: old_tail.clone(),
        }));

        if let Some(ref old) = old_tail {
            old.borrow_mut().next = Some(new_node.clone());
            new_node.borrow_mut().prev = Some(old.clone());
        }

        self.tail = Some(new_node.clone());
        if self.head.is_none() {
            self.head = Some(new_node);
        }
        self.len += 1;
    }

    /// Pop from the front. We clone the `next` link before we mutate anything,
    /// clear the next node's `prev`, then unwrap the old head.
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;
        let next = old_head.borrow().next.clone(); // temporary borrow to clone link

        if let Some(next_rc) = next {
            next_rc.borrow_mut().prev = None;   // break back-link
            self.head = Some(next_rc);
        } else {
            self.head = None;
            self.tail = None;
        }
        self.len -= 1;

        // At this point old_head is only held by our local variable.
        // Its internal `next` still points forward, but that doesn't affect
        // old_head's Rc count—only clones of old_head do.
        Rc::try_unwrap(old_head).ok().map(|cell| cell.into_inner().value)
    }

    /// Pop from the back (the one you asked about specifically).
    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;
        let prev = old_tail.borrow().prev.clone(); // clone back-link, then drop borrow

        if let Some(prev_rc) = prev {
            prev_rc.borrow_mut().next = None; // break forward-link
            self.tail = Some(prev_rc);
        } else {
            self.head = None;
            self.tail = None;
        }
        self.len -= 1;

        Rc::try_unwrap(old_tail).ok().map(|cell| cell.into_inner().value)
    }

    /// Peek at front without removing.
    pub fn peek_front(&self) -> Option<Rc<RefCell<Node<T>>>> {
        self.head.clone()
    }

    /// Peek at back without removing.
    pub fn peek_back(&self) -> Option<Rc<RefCell<Node<T>>>> {
        self.tail.clone()
    }
}

/// Because both directions are `Rc`, nodes form cycles.
/// We manually drain the list on drop so everything gets freed.
impl<T> Drop for List<T> {
    fn drop(&mut self) {
        while self.pop_back().is_some() {}
    }
}

impl<T> Default for List<T> {
    fn default() -> Self {
        Self::new()
    }
}

// ------------------------------------------------------------------
