use std::cell::RefCell;
use std::rc::Rc;

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. We clone `self.head` into the new node,
    /// then borrow the *old* head and the *new* head separately.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(), // clone Rc, not borrow
        }));

        if let Some(old_head) = self.head.take() {
            // Borrow old head mutably -> update its back-link
            old_head.borrow_mut().prev = Some(new_node.clone());
            // Borrow new node mutably -> update its forward-link
            new_node.borrow_mut().next = Some(old_head);
        }

        self.head = Some(new_node.clone());
        if self.tail.is_none() {
            self.tail = Some(new_node);
        }
        self.len += 1;
    }

    /// Push to the back. Symmetric to push_front.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(old_tail) = self.tail.take() {
            old_tail.borrow_mut().next = Some(new_node.clone());
            new_node.borrow_mut().prev = Some(old_tail);
        }

        self.tail = Some(new_node.clone());
        if self.head.is_none() {
            self.head = Some(new_node);
        }
        self.len += 1;
    }

    /// Pop from the front.
    /// 1. Take the head `Rc`.
    /// 2. Read (and clone) its `next` pointer inside a temporary borrow.
    /// 3. Clear the back-link from the next node.
    /// 4. Update `self.head` (and `tail` if the list is now empty).
    /// 5. Break links on the removed node, then `try_unwrap` it
    ///    (reference count is now 1) to extract `value`.
    pub fn pop_front(&mut self) -> Option<T> {
        let old_head = self.head.take()?;

        // Read next pointer; borrow is dropped at end of block
        let next_rc = {
            let borrow = old_head.borrow();
            borrow.next.clone()
        };

        // Break the back-link so old_head's count drops to 1
        if let Some(ref next_node) = next_rc {
            next_node.borrow_mut().prev = None;
        }

        self.head = next_rc;
        if self.head.is_none() {
            self.tail = None;
        }
        self.len -= 1;

        Rc::try_unwrap(old_head)
            .ok()
            .map(|cell| cell.into_inner().value)
    }

    /// Pop from the back. Mirror image of pop_front.
    pub fn pop_back(&mut self) -> Option<T> {
        let old_tail = self.tail.take()?;

        let prev_rc = {
            let borrow = old_tail.borrow();
            borrow.prev.clone()
        };

        if let Some(ref prev_node) = prev_rc {
            prev_node.borrow_mut().next = None;
        }

        self.tail = prev_rc;
        if self.tail.is_none() {
            self.head = None;
        }
        self.len -= 1;

        Rc::try_unwrap(old_tail)
            .ok()
            .map(|cell| cell.into_inner().value)
    }
}

/// Critical for robustness: without this, `prev`/`next` cycles keep
/// nodes alive forever even after the list is dropped.
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        while let Some(current) = self.head.take() {
            // Clone the forward pointer before we break anything
            let next = {
                let cur_ref = current.borrow();
