use std::cell::RefCell;
use std::rc::Rc;

pub struct DoublyLinkedList<T> {
    front: Option<Rc<RefCell<Node<T>>>>,
    back: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            front: None,
            back: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. We clone `self.front` *before* taking it so the
    /// new node's `next` points to the old head.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.front.clone(), // snapshot current head
        }));

        if let Some(old_front) = self.front.take() {
            // Borrow old head only long enough to update its `prev`
            old_front.borrow_mut().prev = Some(Rc::clone(&new_node));
            self.front = Some(new_node);
            // `back` is unchanged (unless list was empty, handled below)
        } else {
            // List was empty: new node is both front and back
            self.front = Some(Rc::clone(&new_node));
            self.back = Some(new_node);
        }
        self.len += 1;
    }

    /// Push to the back. Symmetric to `push_front`.
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.back.clone(), // snapshot current tail
            next: None,
        }));

        if let Some(old_back) = self.back.take() {
            old_back.borrow_mut().next = Some(Rc::clone(&new_node));
            self.back = Some(new_node);
        } else {
            self.front = Some(Rc::clone(&new_node));
            self.back = Some(new_node);
        }
        self.len += 1;
    }

    /// Pop from the front.
    /// 1. Take the front `Rc`.
    /// 2. Read its `next` via a temporary borrow, clone the `Rc`.
    /// 3. Break the link from the new front back to the removed node.
    /// 4. Update list pointers.
    /// 5. `try_unwrap` succeeds because we've broken all other references.
    pub fn pop_front(&mut self) -> Option<T> {
        let front_rc = self.front.take()?;
        let next_rc = front_rc.borrow().next.clone(); // temporary borrow

        // Separate borrow on the neighbor (the new front)
        if let Some(next) = next_rc.as_ref() {
            next.borrow_mut().prev = None;
        }

        self.front = next_rc;
        if self.front.is_none() {
            self.back = None; // list became empty
        }

        self.len -= 1;

        // At this point only `front_rc` holds this node
        let node_cell = Rc::try_unwrap(front_rc).ok()?;
        Some(node_cell.into_inner().value)
    }

    /// Pop from the back. Mirror image of `pop_front`.
    pub fn pop_back(&mut self) -> Option<T> {
        let back_rc = self.back.take()?;
        let prev_rc = back_rc.borrow().prev.clone(); // temporary borrow

        if let Some(prev) = prev_rc.as_ref() {
            prev.borrow_mut().next = None;
        }

        self.back = prev_rc;
        if self.back.is_none() {
            self.front = None; // list became empty
        }

        self.len -= 1;

        let node_cell = Rc::try_unwrap(back_rc).ok()?;
        Some(node_cell.into_inner().value)
    }

    /// Peek without removing (requires `T: Clone`).
    pub fn front(&self) -> Option<T>
    where
        T: Clone,
    {
        self.front.as_ref().map(|n| n.borrow().value.clone())
    }

    /// Peek at back.
    pub fn back(&self) -> Option<T>
    where
        T: Clone,
    {
        self.back.as_ref().map(|n| n.borrow().value.clone())
    }

    pub fn clear(&mut self) {
        while self.pop_front().is_some() {}
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

fn main() {
    let mut list = DoublyLinkedList::new();

    list.push_back(10);
    list.push_front(5);
    list.push_back(20);
    list.push_front(1);

