    head: Option<Rc<RefCell<Node>>>,
    tail: Option<Rc<RefCell<Node>>>,
    len: usize,
}

impl DoublyLinkedList {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push_front(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        if let Some(head) = self.head.as_ref() {
            head.borrow_mut().prev = Some(new_node.clone());
        } else {
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    pub fn push_back(&mut self, value: i32) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(tail) = self.tail.as_ref() {
            tail.borrow_mut().next = Some(new_node.clone());
        } else {
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    pub fn pop_front(&mut self) -> Option<i32> {
        let old_head = self.head.take()?;
        let next = old_head.borrow().next.clone();

        if let Some(next_node) = next.as_ref() {
            next_node.borrow_mut().prev = None;
        }

        self.head = next;
        if self.head.is_none() {
            self.tail = None;
        }
        self.len -= 1;

        let value = old_head.borrow().value;
        old_head.borrow_mut().next = None; // clean up
        Some(value)
    }

    pub fn pop_back(&mut self) -> Option<i32> {
        let old_tail = self.tail.take()?;
        let prev = old_tail.borrow().prev.clone();

        if let Some(prev_node) = prev.as_ref() {
            prev_node.borrow_mut().next = None;
        }

        self.tail = prev;
        if self.tail.is_none() {
            self.head = None;
        }
        self.len -= 1;

        let value = old_tail.borrow().value;
        old_tail.borrow_mut().prev = None; // clean up
        Some(value)
