use std::cell::RefCell;
use std::rc::Rc;

pub struct Node<T> {
    value: T,
    prev: Option<Rc<RefCell<Node<T>>>>,
    next: Option<Rc<RefCell<Node<T>>>>,
}

pub struct DoublyLinkedList<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> DoublyLinkedList<T> {
    pub fn new() -> Self {
        Self {
            head: None,
            tail: None,
            len: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push to the front. Never borrows `head` and `new_node` at the same time.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: None,
            next: self.head.clone(),
        }));

        if let Some(ref head) = self.head {
            head.borrow_mut().prev = Some(new_node.clone());
        } else {
            // List was empty; tail is also the new node.
            self.tail = Some(new_node.clone());
        }

        self.head = Some(new_node);
        self.len += 1;
    }

    /// Push to the back (included for completeness).
    pub fn push_back(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node {
            value,
            prev: self.tail.clone(),
            next: None,
        }));

        if let Some(ref tail) = self.tail {
            tail.borrow_mut().next = Some(new_node.clone());
        } else {
            self.head = Some(new_node.clone());
        }

        self.tail = Some(new_node);
        self.len += 1;
    }

    /// Pop from the front.
    pub fn pop_front(&mut self) -> Option<T> {
        let head_rc = self.head.take()?;
        // Clone the pointer before we start mutating links.
        let next_rc = {
            let borrowed = head_rc.borrow();
            borrowed.next.clone()
        };

        if let Some(ref next) = next_rc {
            next.borrow_mut().prev = None;
        } else {
            self.tail = None;
        }

        self.head = next_rc;

        // At this point only `head_rc` references the old head.
        let node = Rc::try_unwrap(head_rc).expect("internal consistency: head RC > 1");
        self.len -= 1;
        Some(node.into_inner().value)
    }

    /// Pop from the back — the pattern you asked about.
    /// We read `prev`, drop the borrow, clear the link on `prev`, then unwrap.
    pub fn pop_back(&mut self) -> Option<T> {
        let tail_rc = self.tail.take()?;
        // 1. Read the previous node (immutable borrow, immediately dropped).
        let prev_rc = {
            let borrowed = tail_rc.borrow();
            borrowed.prev.clone()
        };

        // 2. Mutate the previous node's `next` pointer.
        if let Some(ref prev) = prev_rc {
            prev.borrow_mut().next = None;
        } else {
            self.head = None;
        }

        // 3. Move the tail pointer back.
        self.tail = prev_rc;

        // 4. Unwrap the removed node. The RC should be exactly 1 because
        //    we cleared `prev`'s `next` link and `tail_rc` holds the only reference.
        let node = Rc::try_unwrap(tail_rc).expect("internal consistency: tail RC > 1");
        self.len -= 1;
        Some(node.into_inner().value)
    }
}

impl<T> Default for DoublyLinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

/// Critical: the nodes form an `Rc` cycle (A <-> B <-> C). If we just drop
/// `head` and `tail`, the internal references keep everything alive.
/// We manually walk and sever links so the counts drop to zero.
impl<T> Drop for DoublyLinkedList<T> {
    fn drop(&mut self) {
        // Remove the list's own references first.
        self.tail = None;

        let mut current = self.head.take();
        while let Some(node_rc) = current {
